/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20191202-5","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"総務委員会","time":"午前１０時００分～午後 １時０２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件整理しています。","topics":[{"id":"topic-01","title":"第９１号議案 戸越台複合施設大規模改修機械設備工事請負契約の変更","agenda":"第９１号議案 戸越台複合施設大規模改修機械設備工事請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今回は３.３％上昇とありますけれども、何％ぐらいの上昇があるとこれを適用するという考えになるのか、そこを補足してほしいと求めました。２つ目は、区のほうから相手側に状況を伺うのか、その流れもご説明ほしいと求めました。","respondent":"立木経理課長","answer":"その単価を変更しますと、特段何％というような基準でということは、おそらく国のほうでもなかろうかと考えています。その申請に基づきまして、区と受注者側とで協議をするという流れになってあります。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"今回、もう１つ質問として、こういう上昇したときに、国からの補助金とかと関係してくるのかと。国からはどういう判断が来るかわからないけれども、これは投資したほうがいいということは品川区独自ではできないのか、その辺はいかがか尋ねました。","respondent":"立木経理課長","answer":"それに合わせて区の予定価格、きちんと市場価格は反映されたもので契約はとられているという前提があります。そういったものも見込んだ上での契約金額ということでやっていただいてはいるところですけれども、そこを簡単に変えるわけにはいかないわけです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"そうすると、この増額分は、区が全部支払うという感覚でよろしいのですかというのが１点。そういうときの判断を区としてはどうするのですかという話なのです。","respondent":"立木経理課長","answer":"補助金に関しましては、済みません、私どものほうでは、このスライド条項に基づいて金額、さらに追加ができるのかどうかというのは、分かりかねます。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"受注者側の判断になるのだろうけれども、実際に増額分と請求されたときに、どういう処理をするのですかいうことなのです。誰が処理するのか尋ねました。","respondent":"立木経理課長、品川財政課長","answer":"もともとのご議決をいただいている案件ですので、そこの部分の予算措置はできてあります。これは区の予算の中で見込めない場合は、その部分を手当てするという形になりますので、基本的には一般会計になるかというふうには思ってありま… 補助金の関係ですので、増額等が出た場合については、これはやっぱり国とか都と話し合いの関係で調整するという形になります。国のほうでも補助金が残金としてあれば、そこで配付される、そういうような形になるかと思います。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"その数をどういうふうに管理しているのですか。それともグロスで来てしまって中身はわかりませんという状況なのか、どうなのか尋ねました。","respondent":"品川財政課長","answer":"説明が不足だったかもしれませんが、補助金というのは、国や都が一定の予算を持ちまして、その中で配分がされるです。そこまでしなくても、国や都で配分ができるということであれば、そういうふうに対応されるということになります。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"長年議員をやっていますけれども、済みません、あまり知らない部分だったのですが、もう少しすっきりするのかなと思いました。何％の値上がりというのはあると思うのですけれども、そういう形で照合できるのかと思えば、全くそれはできていないという理解でいいか尋ねました。","respondent":"品川財政課長","answer":"補助金の原則的な考えですが、いろいろな補助金で全体の費用の中の３分の２が出ますというような形で制度として決められているところがあります。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"結局は、国が補助金の査定の中で、状況によって「なしね」という場合もあるわけではないですか。そういう状況になっているからしようがないではなくて、なかなか難しいと思いますが、ぜひそういう努力もしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"そして、それぞれ工事をする方の設計者が工事監理もしているわけですから、その方たちがきちんと将来予測も把握して見積もりをつくっているわけです。このようなことをやるということは、正規の今までの見積もりはないわけですから、その辺についてどのようなお考えを持っているのか説明を求めました。","respondent":"立木経理課長","answer":"そちらのほうには、将来的な上昇等の分は見込まれてございませんので、その時点での適正価格という形での単価設定になってあります。将来的な上昇分をなかなか見込めないというところが、より安価なところという形になりますので、そこは見込めない部分になってしまいます。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"逆にお聞きしたいのは、逆にデフレスライド条項があって、それを区が適用したことがあるのですかという話になります。本会議で議決しているのだという話になってしまうので、そこはどうなのかと、ご見解を説明するよう求めました。","respondent":"立木経理課長","answer":"上昇分の１％は企業努力分として見てもらうという形をとっている中では、今回、上程をさせていただいているところです。もう１点、これはもちろんそういった急激な変化が見込まれる場合には適用になるものですが、今まで適用したことはございません。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"その辺は改善を考えてほしいと思うし、そういうアンバランスなやり方は、考え直して対応したほうがいいというふうに思います。意見だけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどのやりとりの中でも、国や都の補助金の話とかも確かに求めていってもいいと思っているのですけれども、やりとりの中で。総額で大体１億２,０００万円ぐらい、その辺を、これぐらいならのめるの判断の根拠の部分を示すよう求めました。","respondent":"立木経理課長","answer":"一番長く残工事をとった段階での見積額でいきますと、増額分としては、３億円程度を見込んでいたところです。この３億円という部分をそのまま、この金額は、補助金の関係等も含めた上でのトータルの判断でやらせていただくということになるかと考えています。","id":"exchange-011"}]},{"id":"topic-02","title":"第９２号議案 第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更について、および(3)第９３号議案 第二戸越幹線整備工事（上流部シールド）請負契約の変更","agenda":"第９２号議案 第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更について、および(3)第９３号議案 第二戸越幹線整備工事（上流部シールド）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"設計変更分のところを伺いたいのですけれども、その辺の対応をする客観的なルールはどういったものがあるのか、そこを説明していただけますか。","respondent":"松本河川下水道課長","answer":"現場のほうから請求等がありまして、実際にこれだけ出ましたというようなことがありますので、そういった書類の審査等があります。あわせまして、そういった施工監理の業者が精査した分も含めまして、上がってきた書類等を精査して妥当と判断し減額をしたものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"に施工監理を委託しているわけですけれども、そこが歯どめになっているという、そういうことになるのでしょうか。それを防止するための仕組みは、どういう形があるのか、改めて伺いたいと思います。","respondent":"松本河川下水道課長","answer":"工事をするに当たって、構築物だとか、いろいろなものをつくる段階があろうかと思います。そこの数量だったり、そういった中で今回もこの泥水の処分の量が違うということがわかりましたので、その段階で今回減額したものです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"第９３号議案のことを伺いたいのですが、見当違いの質問をしてしまうかもしれないのですけれども、その部分について伺いたいのですけれども。","respondent":"松本河川下水道課長","answer":"前面の道路も狭い道路のところで工事をしておりまして、当初、交通誘導員を５名配置して工事をする予定でございました。あわせて警察と協議をした結果、５名から７名に変更がございましたので、そういった中で交通誘導員の人数を変更したものです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"第９２号のほうですけれども、仮設工というのですか、工事をされる前に想定されていたのだと思うのです。後になって、なぜ工期が１５日間延伸になるのか尋ねました。","respondent":"松本河川下水道課長","answer":"１点目の騒音対策等ですが、確かに騒音が当初から見込みがあれば、そういった騒音対策を実施するということは場合によってはあります。この夏季休暇を見込んで延長してくださいというような通達がありましたので、それに合わせて今回変更したものです。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"これはどういう処理をするのですか。これは東京都の受託なので、１００％対応してくれるという認識でよろしいか尋ねました。","respondent":"松本河川下水道課長","answer":"そのとおりです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"減額の場合には、返すと思うのですけれども、それはどういうふうに返すのですか。それはどう、まだまだ支払いのずれが出てくるので、ということなのか。","respondent":"松本河川下水道課長","answer":"ですので、その中で各精算をしていくようなことになろうかと思います。最終的には、来年度に工事が終わりになりますので、そこで精算をしていくというような形になろうかと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"１点だけ。減額を判断されたのか、かなり都の下水道の工事等に関しては厳しい検査があるのかなというふうに思ったのですが、その辺について説明を求めました。","respondent":"松本河川下水道課長","answer":"あわせて、当初、今お話がありましたように、産業廃棄物ということで処分場のほうに出すという予定をしてございました。今回の量につきましては、ちゃんとメーター等をつけておりますので、そういったメーターの量から算出して減量分は把握しています。","id":"exchange-018"}]},{"id":"topic-03","title":"工事請負契約の変更について、(6)第９６号議案 城南小学校校舎・幼稚園園舎改築空気調和設備工事請負契約の変更について…","agenda":"工事請負契約の変更について、(6)第９６号議案 城南小学校校舎・幼稚園園舎改築空気調和設備工事請負契約の変更について…","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"先ほど、第９１号議案でも述べましたが、インフレスライド条項と同様に、デフレスライド条項も作成するなどして、区民にわかりやすい、理解を得られやすい、そういう案をつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"これは契約相手側にはきっちりと説明をされているという理解でよろしいですか。これから請求していただける形になっているのか尋ねました。","respondent":"立木経理課長","answer":"実際に適用ということになりました場合には、事業者に、もちろん個別の案内を出しています。そこら辺はきちんと説明をした上で、申請をいただいているというところで、やりとりはきちんとさせていただいていると考えております。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"その際に、「今回こういう形になりますので請求してください」という話だと思うのですけれども、状況によっては、「大丈夫です」という形もあるだろうし、いや、「もう困っていたのです」という相手方もいらっしゃると思いますけれども、今回はどういう感じに受けとめられたのか尋ねました。","respondent":"立木経理課長","answer":"今回、議案で出てきているのが１０件ということで、再積算をしたりですとか、書類を準備するというのは、相当程度の手間がかかるものです。","id":"exchange-021"}]},{"id":"topic-04","title":"第９８号議案 芳水小学校第２期校舎改築その他工事請負契約の変更","agenda":"第９８号議案 芳水小学校第２期校舎改築その他工事請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"先ほども申し上げましたが、インフレスライド条項と同様にデフレスライド条項も作成し、区民の理解が得られる契約制度をつくっていただきたい。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-05","title":"築その他工事請負契約の変更について、(10)第１００号議案 後地小学校校舎改築その他機械設備工事請負契約の変更について…","agenda":"築その他工事請負契約の変更について、(10)第１００号議案 後地小学校校舎改築その他機械設備工事請負契約の変更について…","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"地中障害物ということですけれども、具体的に何かということと、事前にどのような地中の調査をしたのか、想定することは技術的に難しかったのか、そこをご説明ほしいと求めました。","respondent":"若生学校施設担当課長","answer":"さまざま検討したところ、基礎の位置を若干ずらして設計等の変更を行った上で、そういったところでの確認ですとか検討を行ったことによって。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"伺ったのは、工期が２月末から８月末に変わる、やはりちょっとつらいなというのが正直なところです。伺いたいのは、学校とはどのような調整をされているのか、そこの状況だけ伺いたいと思います。","respondent":"若生学校施設担当課長","answer":"子どもたちに影響がなるべくないような形で検討を進めてまいりまして、３月中旬までに仮使用という形で体育館、グロスで仮にさせていただいて。ただ、３月中には引っ越しを行って、４月以降は子どもたちが入って運営できるような形にするです。","id":"exchange-024"},{"speaker":"田中委員","kind":"確認","question":"済みません、今のに関連してですけれども、たしかプールの利用だったり、運動会のグラウンドをほかの学校から借りていたと思うのですけれども、それは来年の３月以降は大丈夫というか、後地小学校でできるということなのか、そこだけ確認させてもらってもいいか尋ねました。","respondent":"若生学校施設担当課長","answer":"説明が不足して申しわけございません。そちらのほうは整備が終わってからでないと運動会はできませんので、こちらにつきましては、外構工事が終わるまではそういう形になります。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"第１００号議案、第１０１号議案の機械設備、地中障害物の撤去との関連は何なのか。でも、機械とか電気工事ということに関しては、どういう関連性があるのかと思うのですとの意見を述べました。","respondent":"若生学校施設担当課長","answer":"そこまで建築が終わらないと電気、機械というところができないところがどうしてもありますので、そういったところで人件費が発生してくるというところで追加になるものです。","id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"そこも含めて、ある程度、税金をプラスで使ってしまうと認識しました。なるべく事前にわかれば一番いいのかなと思いますが、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"区民の理解が得られる契約制度をつくっていただきたいというのが１つと、通常、そこの現場がやらない場合には別の現場に人工を派遣しているのです。ですから、今後、そういうところも民間の建設業者にもいろいろ相談されて対応することを心がけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問","question":"多分この疑問が残ったままの質問しか出てこないのかと、そういう期間について何か別の単価の基準とか計算方法とか、そういうものがあるのでしょうか。そのあたりについて２つ、地中障害物の撤去にかかる工期、その辺がわかれば説明するよう求めました。","respondent":"若生学校施設担当課長","answer":"１点目、延伸に伴って契約の変更をするに当たっては、区としても設定されている単価に基づいて算定していく。そういったところで折り合いをつけていくというところで変更金額等も決めているところですので、そのとおりに金額が決まるというわけではないです。","id":"exchange-029"},{"speaker":"つる副委員長","kind":"質問","question":"工事の期間の話なので、障害物を撤去するのにどれだけかかるのですかという話。工期自体は半年延びていますけれども、障害物の撤去の作業だけでどれだけかかるのか尋ねました。","respondent":"若生学校施設担当課長","answer":"申しわけございません、答弁漏れ、失礼しました。約４カ月程度のおくれが生じるところで、学校運営を考えますと、工期は８月末というところで６カ月延伸をさせていただいたところです。","id":"exchange-030"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ここもわかれば教えていただきたいのですが、第９９号、第１００号、インフレスライド分があって、設備のところにはインフレスライド条項の適用がなかったということですが、ここのところについて詳しくわかれば説明を求めました。","respondent":"立木経理課長","answer":"インフレスライドの案件に関しましては、電気設備工事のところは、今回、もともとが適用外という形になります。インフレスライドは増額分の１％ほどが事業者、増額分が１％未満になってしまうということで、対象外ということになったものです。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"その部分のところを教えていただきたいのと、その職人たちの賃金はどうなっているのかという部分が気になるのですけれども、わかりやすく説明ほしいと求めました。","respondent":"若生学校施設担当課長","answer":"ですので、平成３０年度に契約を行いまして追加工事をしたです。事実上、ほぼ人件費部分になってありますので、そこは事業者が適正な賃金を引き続き払っていくというところで算定しているという認識です。","id":"exchange-032"}]},{"id":"topic-06","title":"第１０２号議案 後地小学校外構整備その他工事請負契約","agenda":"第１０２号議案 後地小学校外構整備その他工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"後地小学校のところで、今お話のあったとおり、一方通行だったりというのは最初からわかっていることで、契約の相手も同じなので、わざわざ随意契約にしなくても、初めから同じ事業者でよかったのではないかということを確認したくて、その部分を示すよう求めました。","respondent":"若生学校施設担当課長","answer":"改築ですと２年間、それも工期の後ろ２年間しか適用にならないというものがルール上定められているところで、分けたということはあります。都を通じて補助金の考え方について、どうも後ろ２年間というところは、それで一本化できるという判断をしました。","id":"exchange-033"},{"speaker":"田中委員","kind":"確認","question":"確認ですが、今後は随意契約ではなくて、こういった工事の場合は、１つにまとまって出てくるということを確認したいと求めました。","respondent":"若生学校施設担当課長","answer":"どういった契約形態がいいかというのは考えていくべきものと考えていますので、必ず一本化しなければいけないというようなことではございませんので、今後ともそういったところで適切に判断していきたいと考えております。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"これからも人工芝にしていくという方針があるということだったのですけれども、契約の際に、静電気の発生と対策はどのように考えられていくのか。ほかのものには代用できないというか、ほかの案は、人工芝以外は出てこないものなのか、その部分を伺いたいです。","respondent":"若生学校施設担当課長","answer":"は砂ぼこりの防止というところでもやはりメリットがあるというところで進めているところですが、メーカーとも確認したところ、完全には防げない。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"人工芝の砂ぼこり対策というのはとても理解できるのですけれども、いろいろな検討をしていただきたいという、これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-07","title":"第１０３号議案 勝島歩道橋南側エレベーター設置工事委託契約の変更","agenda":"第１０３号議案 勝島歩道橋南側エレベーター設置工事委託契約の変更","exchanges":[{"speaker":"田中委員","kind":"質問","question":"随意契約の場合、経理課は所管課の推薦によって契約がなされると聞いています。推薦した所管課と、どのような推薦理由であったかを伺いたいのでけれども。","respondent":"立木経理課長","answer":"モノレールに隣接する工事でございまして、いろいろ制限等がかかる中で、業者推薦ということでこちらのほうと随意契約をしたです。こちらの工事に関する協定をとってありますので、そちらに基づく委託という形になってあります。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"業者の推薦について聞きたかったのですけれども、後地小学校の外構整備については、推薦書の情報公開を求めて持っているのですけれども、こちらは求めなかったので、その理由だったり、随意契約が妥当かどうかを伺いたくて、その部分をお知らせいただければと。","respondent":"立木経理課長","answer":"済みません、ちょっと説明が足りなかったのですけれども、こちらは随意契約というふうになってありますが、もともとは工事協定を結んでおります。ですので、業者推薦書という形では存在はしてございません。","id":"exchange-038"},{"speaker":"田中委員","kind":"意見","question":"それだったら、本当に苦手な分野なのであれなのですけれども、工事協定を結んでいる中で、この随意契約が発生した理由、最初から決められなかった理由というのか、なぜ随意契約になったのかの部分を、ごめんなさい、本当に苦手な分野なので、お知らせほしいと求めました。","respondent":"立木経理課長、多並道路課長","answer":"モノレールの駅に近いところでのエレベーター設置ということになりますので、東京モノレールと工事に関しての協定を結んでおります。その協定に基づきまして、実際の工事をお願いしているというような契約になっておりますので… 補足してご説明します。経理課長がご説明させていただきましたとおり、やはり鉄道というか、モノレールの運行に支障があってはいけない。","id":"exchange-039"},{"speaker":"田中委員","kind":"意見","question":"だから、なぜ随意契約になったのか、ほかの契約方法がなかったのかという部分をお知らせほしいと求めました。","respondent":"立木経理課長","answer":"ご説明の中で、そこの会社に工事自体を丸ごとお願いするというような形ですので、随意契約の１つの形であるということです。それにしたということは、競争性がないというところが一番大きな理由ということになるかと思います。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"随意契約には、もっと詳しい説明資料が必要かと、情報公開請求をして日にちとかをまたいでというものではないと思うのです。随意契約のときの推薦書、最低限の委員会資料として示されるべきではないのかというふうに思うので、その部分について見解を伺えればと思うのですが。","respondent":"立木経理課長","answer":"この第１０３号議案に関しましては、もともと随意契約で議決をいただいた案件の金額変更ということで、現契約につきましてのご説明は省略しています。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、エレベーターは４億円もするものなのですか。何か随分高いなというのが率直な実感なのですけれども、４億円もするのかというところは率直に伺いたいのですけれども、。","respondent":"多並道路課長","answer":"馬主の方とか、いわゆる仮囲いは防音性能のあるものを設置したほうがいいだろうということになりまして、これが一番大きなところです。大きくは１つはエレベーター、あとの残りはデッキをつくったということで、これが金額としてはこういうことになったという理由です。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"金額が高くなっていますけれども、これは全額品川区が出すのでしょうか。それとも東京都のほうからいただけるものなのか尋ねました。","respondent":"多並道路課長","answer":"防音の対応の件ですけれども、一番最初にやろうと思っていた対応としましては、今も実際にやりましたけれども。どうしても馬の状況を見ると、もう少し重ねた対応が必要だろうということで、一般的な対応に加えてやらせていただいたということなので。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"それと、結局、エレベーターの設置については、品川区もある程度出すということの理解でよろしいでしょうか。例えば、まちづくりの１つのバリアフリーも含めてのことだから、品川区もある一定の負担は強いられるということでの理解でよろしいか尋ねました。","respondent":"多並道路課長","answer":"勝島歩道橋の大井競馬場側のほうは階段が駅舎の中にあるような構造になっていまして、そこを通ってまた階段で出てくるような構造になっています。それ以外の部分については、どうしても補修は区のほうで行うところもありますので、一般財源も投入してやっているところです。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"今のご説明ですけれども、区長が若い世代と意見を交わし、区政に反映させるということは大事なことだと思います。ただ、今のお話ですと、これまで区長と一般区民といいますか、公募した方との今までやっていたタウンミーティングはやめたということか尋ねました。","respondent":"木村広報広聴課長","answer":"区長が区民の方々とお話をして意見交換をするという、そのもの自体はやめてはおりません。継続実施をしておりますが、いわゆる名前あるいは対象、テーマを変えて継続して区民の方の声を聞いているです。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"今まで平成１８年度からやっていたタウンミーティングはやめていないということであれば、なぜ平成３０年度は実施されなかったのですか。陳情の趣旨は、復活してほしいということなので、説明するよう求めました。","respondent":"木村広報広聴課長","answer":"平成３０年度につきまして、予算計上もして実施をする予定ではあったのですけれども、日程とか会場の調整がつきませんで、実施をしておりません。","id":"exchange-046"},{"speaker":"中塚委員","kind":"確認","question":"とりあえず令和２年度以降も区長と区民のタウンミーティングは続けるという考えなのかを確認したいのと、その説明は成り立たないと思うのです。こうやって楽しみにしている方もいらっしゃるわけですから、今振り返ってどうお考えなのか説明を求めました。","respondent":"木村広報広聴課長","answer":"令和２年度は、大学との連携、また別の大学という形を今想定しておりますけれども、そちらで展開をすることを考えております。それはその都度、年ごとで判断をして考えていきたいと思いますが、このいわゆる区長との意見交換という形は継続してまいりたいと考えております。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"継続というのはわかったのですけれども、令和２年は、区長と一般区民のタウンミーティングはやらないということか尋ねました。","respondent":"木村広報広聴課長","answer":"現在は、連携の大学と「しながわ未来トーク」という形で、展開をするということで考えておりまして、広く一般区民の方から公募をしてやるということは、今のところ考えておりません。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"一方、幅広く区民に募集をかけて、区長とタウンミーティングを行うという、両方大事だと思います。令和２年度以降も、ぜひ多くの区民と区長が意見を交わすタウンミーティングを復活していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"ただ、「しながわ未来トーク」とともに、今まで行われていたタウンミーティングの場を両方持つことはできないのですか。やっぱりそういう場はなくすではなくて、両方一緒に続けられてもいいのではないかと思うのですけれども、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"区民相談窓口の電話を含めて、いろいろな形で今、区民の方からのご意見を頂戴しておるところです。もう１つは、それは区長が全部見るような形にしていますし、この未来トークというところもやっていくというような形で考えているところです。","id":"exchange-050"},{"speaker":"田中委員","kind":"意見","question":"行けるような場、そういう機会を設定するのでもいいですし、やりようはいっぱいあると思うのです。この陳情に関しては、タウンミーティングの場を復活させてほしいということなので、そこの部分についてもう少しご説明ほしいと求めました。","respondent":"木村広報広聴課長","answer":"こちらからお話をお伺いに行くというようなスタイル、これをやってみようかというところで、今やっているところです。そういう形で進めてまいりたいと思います。","id":"exchange-051"},{"speaker":"田中委員","kind":"意見","question":"この陳情者の方のように、楽しみにされていた方たちもやはり多くいた中で、これからは対象を絞っていくということになった政策変更というか、それに至った理由、根拠の部分は、どのようなことがあって移行していってしまったのか、その部分をお知らせくださいとの意見を述べました。","respondent":"木村広報広聴課長","answer":"冒頭でもご説明させていただいたところではあるのですけれども、それも大学連携という形で区内の大学の方々ともいろいろ関係もできているところでもありますので、そこでやってみようというような形です。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"それだったら、周知方法をもっと変えるとか、若い世代の声を聞くことを議会が求めていたからとご説明だったのですけれども。区民参画につながる場として復活させてほしいというのは、品川生活者ネットワークは強く賛同したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"須貝委員","kind":"質問・要望","question":"３０分ぐらい出席して皆さんの声を聞くとか、質問したら答えてくれた、ぜひそういうところは努力してほしいと求めました。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"質問ですが、品川区のタウンミーティングなのでしょうか、どうなのでしょうか。そうすると、ちょっとニュアンスが違うのかなと思うのですけれども、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"なかなか難しいところです。はっきりしたお答えにならなくて大変申しわけないのですけれども、私としては、品川区のタウンミーティングというような形で考えております。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"ミーティングですから、そこから考えると、やっぱり今までのタウンミーティングというあり方も考えていかなければならないのではないですか。それに対する意見をいただくというふうに変わってきたのかなというふうに思うのですけれども、その辺の経緯はいかがか尋ねました。","respondent":"木村広報広聴課長","answer":"まさにおっしゃるところです。もう１つ、今回は福祉・健康という形でしたけれども、そういうテーマを絞ってやるというところも主眼に置いてやっております。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな要求とか要望とかご意見をいただく場を設定しましょうというのが今の品川区のスタンスだと私は感じるので、前のようにと言われてしまうと。あれやれ、これやれと指示をするようなものではないのではないかというふうに私は強く思いますので、その点も考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"改めて平成１８年から行ってきて１０年以上続いてきて、１０年間やってきた中での総括というか、その辺がわかれば教えてほしいと求めました。","respondent":"木村広報広聴課長","answer":"１０年間の総括です。そういうふうに話せるような場面があまりなかったのかなというところもありまして、そういうところへ絞ってやっていこうということを考えています。","id":"exchange-058"},{"speaker":"小芝委員","kind":"質問","question":"その前の平成２６年が平成２９年と同じく４５人、４９人というふうに出ておるのですけれども、これは公募する段階で人数制限はかけていたのか尋ねました。","respondent":"木村広報広聴課長","answer":"この平成２７年、平成２８年との大きな違いは、していないかというところです。平成２７年、平成２８年については、特定のテーマに絞って関係者の方にご参加いただいて直接お話をしたです。","id":"exchange-059"},{"speaker":"小芝委員","kind":"意見","question":"平成２９年と平成２６年とでキャパシティの関係もあると思いますけれども、広く公平に意見を言えるような環境を整えていったほうがいいとは思います。言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"つる副委員長","kind":"意見","question":"１点聞きたいのが、この間、どういう人数、どういう階層別にしても、司会進行が基本は時の広報広聴課長だったりするのかなという理解です。そういうやり方、手法という検討材料はいかがか、それをまず参考までに教えくださいとの意見を述べました。","respondent":"木村広報広聴課長","answer":"いろいろな会議、そちらのほうでのグループディスカッションのようなところでのファシリテーターの存在はすごく大事だなというふうに思っています。","id":"exchange-061"},{"speaker":"つる副委員長","kind":"意見","question":"かつて私も予算が９対１でしたので指摘したことがあって、工夫という部分では、さまざまなやり方があるのだと思います。ぜひ、区としてもそういう方向性をやっていくことが、ちゃんと理解していただくという意味でのまさに広報も一方で必要なのかと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いいたします。１０年間やってきた中で課題があって、これからも未来トーク等、さまざまな機会を設けながら進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"小芝委員","kind":"意見","question":"本日結論を出すということで、先ほど、意見を述べましたけれども、声ある声、それを聞くことももちろん大事ですが、声なき声も大事です。いろいろな方法で声なき声を聞くことができる環境を今後備えていけると考えますので、今回のこの陳情に関しては不採択としたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"つる副委員長","kind":"質問・要望","question":"その復活という表現ですから、継続性を持って取り組まれているという理解のもとでの意味で本陳情については、不採択。この内容については、先ほど申し上げたとおり、しっかりとその場がクリエイティブな場になるような工夫を今後もやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということ、態度については採択でお願いいたします。で、幅広い区民の方が自分の意見を区長と交換することができるこちらの区長とのタウンミーティングを復活させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"須貝委員","kind":"質問・要望","question":"１５分でも２０分でも３０分でもいいから、そして話をする、そういう何かをやっている席にどんどん行ってほしいと求めました。話を聞いてくれという、そういう要望を持っている方はたくさんいらっしゃいますので、区からも積極的に前へ出ていってやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"田中委員","kind":"意見","question":"結論を出すで、採択を主張します。さまざま意見を聞く場があって区民参画につながって、区政の運営にもいい方向に働くと思うので、私はぜひ賛同したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。すべきものではないというふうな思いがありますので、今後の事業に期待を込めて、今回は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-08","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"私の一般質問の庁舎のあり方検討の部分で、公文書の部分は総務委員会の所管だと思うので、公文書としての経営会議会議記録要旨についての補足の質問を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"中塚委員","kind":"意見","question":"ルール化はないということであれば、できるということなので、ご本人の希望があればかまわないと思いますし、ほかの常任委員会でも、たまに自分たちのということも行われていますので、ここであえて拒む理由はないと思いますので、よろしいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"そこの仕切りをどうしたらいいのだろうなと、本当は議論したいです、本来は総務委員会でもやりたいです。ただ、行財政改革特別委員会がやると言っていることがあるので、そこの仕切りは、委員長、どうしたらいいのでしょうかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、特別委員会とかぶりがあっても、いわゆる一般質問の所管質問は常任委員会でやるという原則でよろしいのではないかと私は思います。仕組みそのものをどうしようかという議論はどこかでするとしても、現状はそうだということでいいのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"決まりとして行財政改革特別委員会でそれについてはやるというふうに決めているのであれば、ただ、そこにそういう議論があるのかどうかですよね。そういう仕組みがなければ、中塚委員が言うように、総務委員会の中で取り上げるべきなのかと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問","question":"質問したかった内容とかを今言ってみてもいいですか。明日やるかどうかは別としても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"もともとのルールをどうしようかという議論はしっかりすべきだと思いますけれども、従来。なので、もう一度、考え直していただいて、明日ぜひできるようにするのが筋かなと思いましたので、意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問","question":"自分の所管質問を行っていたので、そのときはできたということだったので、私ももしできたらよかったなと思ったのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993969?Template=document&Id=2152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":52802,"voices":290}},{"id":"r01-20191203-6","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"区民委員会","time":"午前１０時００分～午前１１時５７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"「」を聴取いたします。 「羽ばたけ！ アントレーヌ」の開催","agenda":"「」を聴取いたします。 「羽ばたけ！ アントレーヌ」の開催","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"こちらは私から１点だけ伺いたいです。最終チェックが入っているかというのを１点伺いたいのと、４点もろもろ書いてあるのですが、その中に。","respondent":"山崎商業・ものづくり課長","answer":"これは企業の瑕疵ということですから、区の支援の範囲の中で起こるトラブルについては、これはほかの事業活動なり支援サービスでもそうですけれども。ご商売に資するご経験をしていただくような、双方成り立つような形で、事業については慎重に対応してまいる所存です。","id":"exchange-001"},{"speaker":"くにば委員","kind":"確認","question":"商品を販売なさる方たちでしたら、それらの商品は全てチェックなさった上で、問題がないということを確認したものしか販売されない。そちらに関して２点、もう一度ご答弁をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"全て１００％、そのときには事前に入居の契約の中で、瑕疵担保のことなども明記するようなところをもってやらせていただいています。そういった事象を個別に考えて、責任が発生するようなことがあれば、区として真摯に対応していくということになるかとは思っております。","id":"exchange-002"},{"speaker":"くにば委員","kind":"意見","question":"いろいろな区の行政の中であったりすると思いますので、そちらに関しては、ぜひ今後もチェックしてほしいと求めました。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/776686?Template=document&Id=2854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":6778,"voices":18}},{"id":"r01-20191203-7","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"厚生委員会","time":"午前１０時００分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"品川区立東品川高齢者多世代交流支援施設（東品川ゆうゆうプラザ）運営事業者の選定","agenda":"品川区立東品川高齢者多世代交流支援施設（東品川ゆうゆうプラザ）運営事業者の選定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それから、このスケジュールのところなのですけれども、それはいつごろになるのかということを２つ目に教えてほしいと求めました。福栄会がこういうところでの提案をされてきているので選ばれたということはわかるのですけれども、そのところについて教えてほしいと求めました。","respondent":"宮尾高齢者地域支援課長","answer":"２番目の議決のスケジュールですが、この後、令和２年第１回の定例会において上程をさせていただいて、ご審議をいただく予定でおります。３点目、点数をつけることによって、福栄会がもう１事業者を上回ったです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう事業者だったのかという、そこら辺のところも、２つ来たわけですから、２つの中で福栄会がなぜ選ばれたのか。それからもう一つ、選定委員会のメンバーも教えてほしいと求めました。","respondent":"宮尾高齢者地域支援課長","answer":"その項目に沿って、点数づけをさせていただき、結果として福栄会がもう１事業者を上回ったです。その後の選定会議は、委員長を福祉部長が務め、委員は、企画調整課長、福祉計画課長、そして私、高齢者地域支援課長が務めたです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところはぜひ今度の議決のときでも結構ですので、示していただきたいということでお願いしたいと思いますけれども、いかがでしょうか。その書類というのは、もうこの選定の段階で出されているということで考えていいのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"点数につきましては、こちらは区の方針でもありますけれども、こちらは遠慮させていただきたいと考えています。改めてこれから詳細を候補者と詰めていく中で、事業計画というのはまた改めて提出を求めるというものです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"提案の中には、この提案のところでは、職種と人数についてお聞かせほしいと求めました。","respondent":"宮尾高齢者地域支援課長","answer":"資格としては、介護福祉士、社会福祉士または介護支援専門員、もしくは保育士資格を所持している者というふうになっています。それに加えまして、非常勤職員の採用を予定しているというふうになっています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"最後に、先ほど事業計画書とかさまざま、指定管理者に必要な書類というのはこれから出てくるということでしたけれども、いつごろ出されるかということだけ説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"開設から逆算をして、しっかり余裕を持って、我々もそれを受けとめて、話し合い、相談ができる期間を持った上でと考えています。具体的な期日につきましては、まだ現在では未定です。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"ワーカーズコープがもう１事業者であったということですが、高齢者事業ですとか多世代関係、あるいは子ども食堂。これだったら、刺激があって全体が高まっていくという考え方もあるかと思うのですけれども、結局どこで差がついたのかもう一度教えていただけますか。","respondent":"宮尾高齢者地域支援課長","answer":"両事業者を審査員が審査をさせていただき、点数化をして、最終的に福栄会がもう１事業者を上回ったという内容になっております。こちらではあれですけれども、まず大きく差がついた点といたしましては、施設の設置目的を達成するために十分な能力を有しているかというところで。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"そんなに大きな差がつくというのは、私としては不思議だなという気がするのですが、質問を変えます。今、東品川も含めてゆうゆうが幾つあって、それぞれどこが運営しているか説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"そして、今年の３月にオープンをいたしました平塚につきましては、福栄会にお願いをしています。そして、今回東品川がまた同様に福栄会のほうにお願いをする予定です。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"先ほど鈴木ひろ子委員の質問にもありましたように、もっと情報公開をしていくべきだと思いますし、そのほうが区のためになると思います。といいますのは、また質問の方向が変わりますけれども、今福栄会に品川区からのＯＢの職員は何人いますか。","respondent":"大串福祉計画課長","answer":"今、福栄会のほうにＯＢということで行ってらっしゃるのはお二人です。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"外形的な客観性を担保するためには、選定基準をさらにオープンにしていかないと、これは区の信用にかかわるところではないかと思います。スケジュール等々についても、よりオープンにしていくことが区のためにもなるのではないかと思いますが、ここはご意見を伺いたいところです。","respondent":"大串福祉計画課長","answer":"企画部門の所管ということになっておりますので、その辺全体の流れと、指定管理については考えていければと考えております。ご指摘いただいた透明性等々、こういったところも重要な問題だとは認識をしておりますので、その辺については検討していければと考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国のほうもそういう方向を求めているというのもあると思うのです。ワーカーズコープと福栄会で、最終的なトータルの点数だけでも何点かということは、ここでお答えいただくということはできないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところも含めてぜひご検討いただきたいということで、ご意見を申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"渡部委員","kind":"確認","question":"右側の多職種連携システムの取り組みについて伺いますと、訪問看護だろうが、それこそさまざまな連携がとれてはいくのだと資料を見て思う。在支が１７２人とか、ではどういうふうに同意をとっていって、ざっくり教えてほしいと求めました。","respondent":"大串福祉計画課長、寺嶋高齢者福祉課長","answer":"ブロックごとでの課題、対応、こういったものが出てきて、それが品川区全体として、これが広範に活用できれば一番いいのかなと考えているところです。次年度以降こういった形でする際には、検討していきたいというふうに思っております。先ほど福祉計画課長の説明の中でもあったとおり、まだまだ事業者関係の登録状況は非常に低いというところは重々認識しています。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"２点お伺いしたいのが、区内に結構あると思うのですが、そういうところというのはどういうふうに連携をとられていくのか。逆にそういうところはせっかくですから、会のほうに所属していただいてというのも１つの手だと思うのです。","respondent":"大串福祉計画課長、寺嶋高齢者福祉課長","answer":"現実問題、荏原医師会等々に入っていないクリニックの先生もこのブロック会議にはお呼びをしています。医師会加盟、非加盟といったところではなく、在宅医療… 少なからずご説明はきちんと聞いてはいただけているような状態で、まず１点申し上げておきたいと思います。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"そこの問題については、セキュリティー上大丈夫ですかと聞こうと思ったのですが、そこまで考えてお答えいただいてありがとうあります。例えば大田区だったり、何らかの形で品川区はこういう仕組みをやっていますというアナウンスが入るのかどうなのかだけ最後にお聞きして終わります。","respondent":"寺嶋高齢者福祉課長","answer":"考え方としては、今こうした実例があったという話は担当からは聞いていないのでわからないですが、考え方としてはあります。そこまで実際には手が回っていないところがあるのですけれども、検討課題としては認識しております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"メンバーであったり、そういうところで何かこれに基づいてありますよみたいなそういう要綱みたいなものはつくられるのでしょうか。それからもう一つ、どういうふうに選ばれるのかということなのですが、その中から２０名というのをメンバーとして選ぶということになるのか尋ねました。","respondent":"大串福祉計画課長","answer":"したがって、医師会の皆さん方にもご説明をさせていただきながらいろいろなご意見をいただく、皆さんからご意見をいただいた中でといったところです。基本的にはこのお二人が会議を仕切るというとあれですけれども、進めていただく形でお願いをしているところになります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"８人のブロックリーダーが集まって、具体的な解決策を提案、そういうふうな形で進めるということになっていくのでしょうか。そういうシステムのところで課題があるという、そこはどういう意味なのかなというふうなところ、そこら辺のところの区の認識を伺えたらと思いますとの意見を述べました。","respondent":"大串福祉計画課長","answer":"やはり進め方、まずはそういったブロックリーダーの皆さん集まっていただいて、お話しする機会を１回設けさせていただいている。より深い連携をしていくことが地域包括ケアの推進、このブロック会議であるとか連携システムの深化、こういったものを図っていければと思っています。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"いろいろと多職種連携のそういう仕組みというのは地区ケア会議しかなかったところに今回これがプラスという、そういうイメージでいいのでしょうか。他区の多職種連携とあわせてどうなのかというあたりも教えていただけたらと思います。","respondent":"寺嶋高齢者福祉課長","answer":"実際には連携が最も必要であろう２職種というところでは、関与している方で、それが実務上一番必要なことでやっていたということです。今現在も地域ケア会議として継続しているのですけれども、当然、その辺はまた進みながら検討していくことは必要であろうと考えております。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"確認をとられた方、この確認をとるときには、これらの情報を全て共有することになりますという確認をとられているのか。それは大事な部分もあるので、そこら辺の捉え方と、確認がとられているのかというとことを１つお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"私の説明の仕方がよくなかったようで、在宅介護支援システムという形で、まずはシステム開発です。１つとしてつくり直したということ、申し訳ありません、そういうことがあります。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それとも、患者・利用者の登録状況の３,７３０人ということなのですけれども、これはどのように選ばれていくのか。それともサービスを使っている方は皆さん登録してもらうということになるのか、そこの仕組みだけ説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"ただ、それぞれ支援してくれている方が新たな情報を共有して、わかっていただいた上で次の支援にあたりますよというご案内はしています。それが実際の動きです。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"共有すべきではない情報もあるため、そのようなことの整理ということが介護保険制度推進委員会の中でも言われていたのです。共有すべきでない情報もあるというところなのですが、誰が判断をして情報を入れていくということになるのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"それから医療の方をあわせて、そういったどういう項目が必要かという打ち合わせをしまして、例えば項目の洗い出しを実際に行っております。検証しながら進めているということもあるので、数回の打ち合わせを経て、一定程度情報の絞り込みができております。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、この情報をアップするということに対しては、共有すべきでない情報というものを除いて、この情報だったらいいのではないかというふうな、共有する情報として設定するというところは、最終的には区が責任を持つということでいいということか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"システムに関係しての責任は全て品川区にありますので、品川区が責任を持ってやっていきます。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"その際に、ブロックというのが今ざっくりと直線で引かれていますけれども、これはある程度のイメージということなのでしょうか。特に高齢者医療をイメージしているかと思うのですけれども、今後これが障害ですとかそうした形で別の医療に広げていくお考えはあるか尋ねました。","respondent":"大串福祉計画課長","answer":"どういう周知方法がいいのかといったことについても検討していただき、まずは専門職の中でご意見をいただければと考えています。ぜひ聞いてみたいということで来ていただいているケースもあるので、決して門戸を狭めてどうこうと考えているものではありません。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"これまで医療機関、特に総合病院を含めた医療機関と自治体、区との関係というのはなかなか持ちにくい部分があったかなと思います。これは行政によって、これまでなかなか課題として進んでいなかったところがこれによって進んでいくという期待もしてよろしいのか尋ねました。","respondent":"大串福祉計画課長","answer":"そういったお声を受けて、こういった機会を設置していくのも必要ではないかなと考えているところです。そういった意味では、少しでもこういった形で連携が深まっていければ、最終的には区民の福祉の向上につながるものではないかと考えているところです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"確認","question":"関係が地域ごとにできていくということも、多職種連携システムを進めていく上での１つの土壌づくりと捉えていいのかということを１点お伺いします。それとも３千人分が全部見られるのかということを確認したいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"わかりやすく、ビジュアル的に説明があるとなお興味を持っていただけると思いますので、これは確実に地域ケアブロック会議の力は借りて。同意した３,７００人の分が見られるかというと、そんなことはなくて、担当している方の情報しか見ることはできないです。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"そうした意味から、事業者あるいはクリニックなども含めて、そうした専門職の方々や組織に何かインセンティブみたいなものはあるのですか。インセンティブがないとなかなかお願いだけでは、仕事が確実に増えるのは増えるので、どうなのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"お聞きするところ、「うちはセキュリティーの問題で、「それならもう少し様子見させてください」というような話があったと。まだ現場の介護側のほうから、件数が増えればそういうこともあり得ますので、そこはしっかり情報収集していきたいと思います。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"違うシステムだということですので、そこら辺もどういう意向がいいのかも含めて進めてほしいと求めました。すみません、このシステムを構築して運用する事業、これはどこが財源になっているのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"これは、平成２９年度の介護保険特別会計の中の、いわゆる総務費というところで計上されていまして、６億円弱の経費がかかっています。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問","question":"このシステム自体も、品川区オリジナルのシステムと考えていいのでしょうか。そうすると、区をまたいだ病院とかクリニックというのは、ここには入ってきようがないという感じなのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"１：６ぐらいの比率なので、ほとんどカスタマイズの費用のほうが高いということで、そういう意味ではほぼオリジナルといってもいいのかなと思います。多職種連携システムはインターネット環境が整っていれば、仮想のサーバーのところでアクセスをするので、技術的には可能です。","id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この地域ケアブロック会議にしても、多職種連携システムの取り組みにしても、東京都とかのかかわりがあるのかどうなのか。別にガイドラインとかがあるわけではなくて、この取り組みは区独自で医療と介護の連携というものの中で考えてきたものということか尋ねました。","respondent":"大串福祉計画課長","answer":"地域支援事業の実施ということで、通知もいただいているところです。それに基づいて、介護と医療の連携については取り組んでいるといったところです。","id":"exchange-028"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"２点確認させてください。確かサーフという愛称にしましたみたいなものを読んだことがあるのですけれども、一体そこはどういうかかわりになっているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"区民の方が障害児者総合支援施設というのが言いづらいというのもあって、そこは事業者のほうとも話をさせていただきまして、今回の公募に至っているです。","id":"exchange-029"},{"speaker":"あべ委員","kind":"意見","question":"私が言うまでもないことではありますけれども、事前にここはお話をしておくべきところだったと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312511?Template=document&Id=3552#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":38238,"voices":87}},{"id":"r01-20191203-8","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"建設委員会","time":"午前１０時００分～午後 ０時０９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)「東京における都市計画道路の在り方に関する基本方針」の策定・公表","agenda":"はじめに、(1)「東京における都市計画道路の在り方に関する基本方針」の策定・公表","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"補助３０号、補助２７号、補助３１号についてどのような意見を言ったのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"３１号線等については基本方針の６８ページになりますが、（１）既存道路による代替可能性というところで、検証がなされてあります。ご質問の３点目、特に補助３１号線のところについては、当然東京都と一緒に検証を行ったところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"第四次優先整備路線の整備期間ですけれども、これが終わった後の１０年間で全て整備、着手するというお考えなのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"当然ながらその第四次の中で示された道路整備を計画的に行っていく、その後、第五次事業化計画の策定が進められていくことになると思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"パブリックコメントにもありますように、やはり整備をするべきではないと、廃止するべきだという意見も出ております。この具体化に当たっては、きちんともう一度、繰り返しになりますけれども住民の意見を交えた検証をするよう、求めていってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"大井町駅周辺のまちづくり方針の策定および広町地区におけるまちづくりの検討状況","agenda":"大井町駅周辺のまちづくり方針の策定および広町地区におけるまちづくりの検討状況","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"住民参加で進めていくべきだと思っているのですが、それともこれから策定しますよという報告なのか、伺いたいと思います。何を定めるのか、特に空間形成方針というのは一体何を指して、何を定めるものかということについても伺います。","respondent":"稲田都市開発課長","answer":"例えば広町地区に動きが出てきておりますので、その辺を見据えた、ご指摘のようなより具体的な方針がまとめられればと考えているところです。空間形成方針というのは、そういうものの空間形成の方針といったところでございまして、挙げているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"その後の地域の説明会ですが、その対象範囲はどこになるのでしょうか。その開催予定時期についても伺いたいと思います。","respondent":"稲田都市開発課長","answer":"この方針の地域への説明ですが、まちづくり組織等があればその辺等にまずは、説明をしてご意見を伺いたいと考えています。４月以降の策定ということで、具体的にはまだで、来年度早々ぐらいにはつくっていければという予定で考えているところです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"昨年度は広町地区プロジェクト推進会議という名前で、９回開催されている会議体がありますけれども、それが検討体制ということでしょうか。この構成メンバーと、今年度は何回ぐらい開催されてきたのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"それから広町地区の検討です。名称的にプロジェクトという名前をつけましたけれども、そういう会議で検討を行ってきているというものです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"それ以外にも例えばアンケートをとるなどで、地域住民の声を聞く手段をとるべきだと思いますけれども、いかがでしょうか。もう少し、どういうことを合意しようとする内容なのか、伺います。","respondent":"稲田都市開発課長","answer":"一歩進んでしっかりと検討を進めなければいけないというところで、駅側をＪＲ、地に足がついた検討が進められるかと考えています。それと事業手法も考えながらやらないとできませんので、東京都や関係部署さまざまありますので、その辺とさらに調整を進めていくです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"その上で伺いますけれど、今回の土地再編の具体化をしようという動きだと思うのですけれど、これで一体何が確定されるのでしょうか。土地再編を行う時期というのは、いつごろを考えておられるのか、あわせて伺います。","respondent":"稲田都市開発課長","answer":"飛び地をこのように再編することによって、より有効的な土地利用ができていくということで検討してきているものです。いつごろかですが、この辺の検討が進んだ暁には、そういう合意を結んでいくものと予定しております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"再編するかどうかということも含めて、庁舎の問題がかかわっているわけですから、情報公開をしてやるべきだということをずっと言ってきました。一刻も早く住民参加の会議体をつくり、検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"先ほどまだたたき台で、方針自体、区の内部でまだまだ検討しなければいけないというご答弁があったように思います。現段階で、区内部での検討には、どのような部署が参加し、どういうことについて検討されているのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"この方針の検討状況ですが、我々都市開発課の中で検討している状況です。私たちがやっていることがある程度になってくれば、今後関係部署等に説明をして、ご意見を伺いながらやっていくと。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"都市開発課の検討はどの辺まで固まったら関係部署に説明していくのか、関係部署はさまざまあるとおっしゃいましたが、本当にさまざまだと思うのです。その辺、現段階でこことここは必ずとか、考えていらっしゃるところがあったら教えていただきたいのですが。","respondent":"稲田都市開発課長","answer":"もちろんその他の部署にも話をしなければいけないということもあります。一部、話を切り出ししている部分もありますけれども、並行しながらやっていきたいと考えております。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"説明会となると、皆さん参加された方は、自分たちの意見は聞いてもらえないというご感想をよく聞きます。そうならない段階でぜひ示していただきたいと思うのですけれど、その辺のスケジュール感といいますか、お考えがあったら説明を求めました。","respondent":"稲田都市開発課長","answer":"スケジュール感ですけれども、４月以降に決定していきたいということになれば、単年度内に関係部署等に話をしていきたいというところはあります。来年４月以降、地域の皆様方にもお示しできればと考えていますが、それをご説明しながら意見を伺っていくという形です。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"きちんと地元への説明をしてほしいということ、それだけでなく、さまざまな子ども施策とかにかかわる方たちも入ってほしいと求めました。これは是非ということで、要望にとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは要望しておきます。今、ご答弁をといってもなかなか、これからだという話になるでしょうから、要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ福祉とか保育の関係部署も入れてほしいという要望は言ったのですけれど、車いすをお使いの方、私たちにわからない影響が出てくると思います。ぜひ地域への説明とか、地元関係者への説明の中にはそういう方々も入れて、ご意見がきちんと反映できる形での説明会の実施を要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-03","title":"大崎駅東口第４地区まちづくりガイドライン（案）","agenda":"大崎駅東口第４地区まちづくりガイドライン（案）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"連絡会の構成について伺いたいのですけれど、そこも含めて「など」に当たるところを全て、教えてほしいと求めました。こちらには自主的なまちづくり支援ということで、活動費などの補助金などは出ているのか、伺います。","respondent":"稲田都市開発課長","answer":"それから「など」ですけれども、マンションが２棟、間にあるのです。３つ目のまちづくり補助金、いわゆるまちづくりに関係する補助金という形では、出ていないということです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"確認","question":"フジタも入っているというふうに聞いたのですけれど、開発協力企業はその３社でいいのか、確認させてください。そこら辺についてはどうか尋ねました。","respondent":"稲田都市開発課長","answer":"遅れてまちづくりに参加、協議会で検討されてやってきているということで、何とかこのまちづくりをやっていきたいという話です。この開発状況の話も当然しておりまして、その辺で今後も混雑解消に向けてやっていきたいとういうふうに考えております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、協議をしているという話ですけれど、実際に現状の人口から、ここが相当増えることになるわけではないですか。ですから、どうも街並みを誘導していくところは、勉強会にしてほしいと求めました。","respondent":"稲田都市開発課長","answer":"先ほどの訂正です。西側の権利者数は１５名と言ったのですが、済みません、会員数が１５名ということでご理解ください。","id":"exchange-018"}]},{"id":"topic-04","title":"ゆうぽうと跡地開発計画におけるホール施設の賃借","agenda":"ゆうぽうと跡地開発計画におけるホール施設の賃借","exchanges":[{"speaker":"松本委員","kind":"質問","question":"３０年間の契約でかなり長期に及ぶということで、かなり時間があるということで、この間に価値は大分変わるのではないかと思っています。賃料がある程度この辺だというのが確定していくのは、どのぐらいのタイミングになるとイメージすればよろしいか尋ねました。","respondent":"稲田都市開発課長","answer":"着工前の予約契約というのを行うのですけれども、大体そこで絞り込んでいけるのではないかと。最終的には本契約を行うのですけれども、今の段階では、１億４,０００万円を上限として、賃料を考えていくというところでやっています。","id":"exchange-019"},{"speaker":"松本委員","kind":"質問・要望","question":"本契約締結時点で大分下がっているということは、今後あり得るのではないかと思っていますので、そこの部分はできるだけ、賃料の交渉部分は流動的に、ぎりぎりのところまで行っていただきたいというところは、要望として挙げします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問","question":"３０年間の中で、例えば１０年ごとに契約を見直すとか、そういう内容を入れたりすることはできなかったのか。区がこれを借りるので、このホールの運営管理等は、指定管理、委託とかで行うことになるのか尋ねました。","respondent":"稲田都市開発課長","answer":"今後、運営をどのようにしていくかというところも、区の中で検討していくところです。日本郵政不動産株式会社にも考えはありますけれども、区のほうの考えもしっかり伝えていきたいと考えています。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問・要望","question":"地域の方とかいろいろな団体の方が今まで、３０年間ずっと変わらずというざっくりした形でなく、ぜひよりよい形でお願いしたいと思います。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それでホールの面積が、今お伺いすると４００平米と１００平米で、合計５００平米です。１億４,０００万円の中でどういうふうに分けているかわからないですけれど、バックヤードの賃貸借に割引とか、そういうものはあるのか尋ねました。","respondent":"稲田都市開発課長","answer":"そういうもろもろありまして、ホールとそういうもので２,４００平米です。現在この２,４００平米で１億４,０００万円という形での設定で、やっているところです。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"最終的に金額を決めて、経理課に渡すところまでは、ここの所管が最終的にやっていくという理解でよろしいでしょうか。総務委員会に出されていくのか、それとも金額が決まった段階で最終的な判断なのか、その辺の手順だけ説明を求めました。","respondent":"稲田都市開発課長","answer":"都市開発課がアンケート等でいろいろ調査を行ってきて、今、この段階まで来ているです。しばらくは私どものほうと、企画担当部署で検討しながら、どのような方向性で行くかというふうになっていくかと思います。","id":"exchange-024"},{"speaker":"吉田委員","kind":"確認","question":"確認ですが、具体的なところまでは所管課でやっていくということで、よろしいのですよね。契約という話しで、その金額の妥当性となると、最終的には総務委員会の議題にあがるということで理解して、よろしいということですよね。","respondent":"稲田都市開発課長","answer":"今回、基本的な協定を結んで、ようやく契約というところで、考えているところです。それを詰めながら、実際の部署がどこになるのか、です。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"ホールの位置づけについて区はどのように考えていらっしゃるのか、伺いたいと思います。３点目としては要望ですけれど、そういったことも考えていただけないかと思いますけれど、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"今後、運営の方法とかについて検討し、どのような形で運営していくかということになると思います。今後、区民優先の申し込みなどにおきましては、運営方法をこれから考えていくところですので、その辺で検討していくというふうに考えております。","id":"exchange-026"}]},{"id":"topic-05","title":"第二戸越幹線整備工事（下水道本管立杭整備および上流部シールド）","agenda":"第二戸越幹線整備工事（下水道本管立杭整備および上流部シールド）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"戸越幹線整備工事の完了時期だけ教えてほしいです。完成して、水は大丈夫ですよというのはいつが予定されているかだけ、説明を求めました。","respondent":"松本河川下水道課長","answer":"第二戸越幹線整備工事につきましては、現在令和６年度の完成を予定しております。","id":"exchange-027"}]},{"id":"topic-06","title":"土砂災害ハザードマップの作成および配布","agenda":"土砂災害ハザードマップの作成および配布","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"このハザードマップですが、ホームページなどにアップする予定はあるのでしょうか。そちらは載せたほうがいいのではないか、お知らせすべきではないかと思うのですけれど、いかがか尋ねました。","respondent":"中島防災課長、長尾建築課長","answer":"ホームページのアップにつきましては、こちらの配布のタイミングに合わせまして、行っていく予定です。ホームページに合わせてなのか、周知の仕方については検討しますが、お伝えできるようにしてまいりたいと思っています。 崖自体を所有されている方に対してご利用いただく制度ですので、こちらについては個別に、建築課のほうで周知していく予定としております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に避難情報緊急通知コールですけれど、これはとても大切な事業ではないかと思うのですけれど、現在の登録状況を伺わせてください。登録件数は何件か、実際に稼働された実績はあったのか、あわせてお願いします。","respondent":"中島防災課長","answer":"広報しながわの１１月１１日号にも掲載して、その後登録数は伸びているところですが、今、最新の数字がなくて申しわけございません。運用につきましては、この前の台風第１９号において、避難準備情報あるいは避難勧告等の場面で活用しています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"できればこういった制度があるのですよという声がけも含めて、避難情報緊急通知コールの登録者を増やしていただく努力もしてほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは皆さんも慣れてくるから、ちゃんと避難してくださいということを周知していけばいいわけですから、何事もない場合でもいいのです。それまでにどういうふうに周知なり、また変な理解から危ないということになってしまうので、そこら辺だけ教えてほしいと求めました。","respondent":"中島防災課長","answer":"周りの方にあまり誤解のないような形で、適切な情報発信というのが大事だと考えています。建築課とも連携しまして、周知などの決め事等含めて、誤解のないように努めてまいりたいと考えています。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば別紙２を見て、最初にこの絵で「がけがくずれそうだ！崩れちゃうのみたいな感じになるのではないかと思っていて、言葉の使い方なのですが、そこに関してもしお考えがあれば教えてほしいと求めました。","respondent":"中島防災課長","answer":"やはり高齢者等避難開始から、早目の情報発信に努めて、早い段階での避難情報の発信に努めていきたいと考えています。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"」というのは、変な誤解を与えるような気がしてならないのです。そこだけはちょっとお考えいただきたいという、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"提案","question":"ぜひやってもらいたいということを質問、提案しましたところ、今は全く訓練をやっていないわけです。ですから、そういうことを実際に対象世帯の方を中心にしていただきたいのですが、やってみないと想定できないと思うのですとの意見を述べました。","respondent":"中島防災課長","answer":"例示させていただきました避難誘導ワークショップですが、風水害初動対応等が対象になると思いますが、避難行動要支援者の個別計画も含めまして。そういう講座等も検討していますので、そういう一連の流れでしっかりと、訓練を行っていけるように努めてまいりたいと思っています。","id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"例えば電子音声か何かで、同じものがバッと流れていくのか、その仕組みをお伺いしてもよろしいか尋ねました。","respondent":"中島防災課長","answer":"最初にメールを送らせていただきまして、そこで受信確認ができましたら電話は行わない形になっております。メールの受信が何回か送って確認できない場合は、電話がかかるという仕組みになっております。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"今、順次という言葉が出たかと思うのですが、順次ということは、電話についてはタイムラグがあり得るということか尋ねました。","respondent":"中島防災課長","answer":"失礼いたしました。一斉で、電話をかけるようになっています。","id":"exchange-036"},{"speaker":"高橋（伸）副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ確認させていただきたいのですけれど、そういった啓発を事前にするのかどうか、お聞きしたいと思います。","respondent":"中島防災課長","answer":"今回の１２月７日の一斉防災訓練では、そのような周知を行う予定はございません。","id":"exchange-037"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１１月２９日の須貝議員の災害停電時の中高層マンション対策についてですが、照明についてもどの規模の灯りをつけることが可能なものなのかなど、伺いたいと思います。","respondent":"長尾建築課長","answer":"所管質問に関連いたしまして、発電機設置の義務づけについて、配付いたしましたＡ４の資料で説明いたします。予備電源の最少作動時間は３０分間と定められております。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"停電時は基本的に区民避難所に避難してくださいというのが品川区の方針なのでしょうか。伺いたいと思います。","respondent":"中島防災課長、長尾建築課長","answer":"本会議での答弁の繰り返しになるところもありますが、在宅避難ができる方は在宅避難していただきます。それが難しい場合には区民避難所等に避難をしていただきたいという考えを、区としては持っております。こちらは建築基準法の中で法定で定められている、最低限この時間は作動させてくださいという義務が発生している時間となっております。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"超高層にお住まいの方ですと、大体どれぐらいいらっしゃるとお考えなのか、考え方だけ伺いたいと思います。","respondent":"中島防災課長","answer":"飲み物を最低３日間、なるべく１週間分は確保していただきたいということは、かねてから努めてお願いしています。そちらについてはマンション、戸建て問わず、引き続き啓発していきたいと考えています。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"法定の最少作動時間というのは、どういう行為が終了するだろうというか、その間にこういうことはできるはずということが想定されていると思うのです。エレベーターの場合も、６０分動けば大体の人は外に出られるのか、その辺の考え方を説明するよう求めました。","respondent":"長尾建築課長","answer":"その活動をするために６０分間は最低でも必要ですという設定になっております。３０分間というふうに設定されておりますので、地上出口に向かって避難するというところまでを想定して、最低３０分間という考え方になっております。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。非常用のものは基本そういうものであってということは、きちんと説明されているというふうに理解してよろしいのか尋ねました。","respondent":"長尾建築課長、稲田都市開発課長","answer":"その中で法定で設置される非常用エレベーターのお話は、法定で義務づけられている部分ですので、そこまでの説明がなされているかどうかというのは。それを売りとして考えられている販売業者や事業者であれば… 東京都の新しい都市づくりのための都市開発諸制度活用方針というものがありまして、建築物の自立性の確保に最大限努めなさいというものがあります。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺の情報提供が求められた場合はきちんとできるように、ぜひ考えていってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"３日間とどまれるよう、実際に区内の６０メートル以上というか超高層の建物、お聞かせほしいと求めました。","respondent":"稲田都市開発課長","answer":"どれだけかというところは把握しているものではございませんけれども、７２時間稼働させる非常用発電機を所有しているところは、武蔵小山等におきましてはありますし、ほかの地区でもそういうところがあるという状況です。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/876969?Template=document&Id=4280#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":36038,"voices":130}},{"id":"r01-20191203-9","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"文教委員会","time":"午前１０時００分～午後 ２時３６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件整理しています。","topics":[{"id":"topic-01","title":"旧三井文庫第二書庫の国登録文化財への答申","agenda":"旧三井文庫第二書庫の国登録文化財への答申","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"耐震上の問題があるということで、それは、どういった問題というか、耐震補強などをしなければいけないのか。そういったところを伺いたいのと、今後、国登録文化財となった後、どのようにしていくのか、今後の展開といいますか、伺いたいと思います。","respondent":"有馬庶務課長","answer":"先ほども説明したとおり、この文化的価値がなくなるということで、耐震補強すること自体が少し難しいかと考えております。１つの対象建造物という形で、ヘルメットか何かを被っていただいて、少し見学していただくというようなことは考えております。","id":"exchange-001"},{"speaker":"筒井委員","kind":"意見","question":"そして、今、防災倉庫として、防災用のさまざまな用品などがあると思うのですけれど、それは今度どこに移転するのか。今わかる状況でお知らせほしいと求めました。","respondent":"有馬庶務課長","answer":"今言ったように、若干、耐震性の問題もあるので、内部公開については期間限定みたいな対応をしていきたいと思っています。耐震性が若干足りないということですので、防災倉庫の備蓄品はそのまま、とりあえずは今のところに保管していこうかと考えているところです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"いろいろな支援があるのではないかと思うのですけれども、そういうものが、どういうものがあるのかというところを最初にお聞きするのと。周辺整備の可能性というものとか、考えみたいなものがあれば。","respondent":"有馬庶務課長","answer":"国の支援の関係ですけれども、指定文化財と登録文化財の２つがございまして、いろいろなことに制限がかかってきます。３６５日、公園課ともまた協議しながら、どういう形がいいのかは検討していきたいと考えております。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"意見","question":"区の所有ではないのですけれど、今回は区の所有なので、こういうふうに価値が認められるのは大変よろしいことかと思っています。簡単で結構なのですが、どんな感じのパネルにする予定か、もしわかればお願いしますとの意見を述べました。","respondent":"有馬庶務課長","answer":"今、外に解説板を張ってはあるのですけれども、それとあわせて、どういう展示がいいのかということは、今、内部で検討しております。何かそれだけで終わってしまうというのも、少し寂しいかとは思っていますので、またいろいろと検討していきたいと考えております。","id":"exchange-004"}]},{"id":"topic-02","title":"令和２年度入学希望申請の状況","agenda":"令和２年度入学希望申請の状況","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"最初に、小学校、中学校ともに、受入枠なのですけれど、これは、前年度との比較は出ていないのですけど、それほど変わっていないということでいいのか尋ねました。","respondent":"篠田学務課長","answer":"基本的には、昨年度とほぼ変わっていないような状況です。若干、お子さんが増えている通学区域、あるいは減っている通学区域、それぞれありますが、基本的にはほぼ同じだとご覧いただければと思います。","id":"exchange-005"},{"speaker":"塚本委員","kind":"確認","question":"八潮学園に１４０人、受入枠というところが９０人で出ているという意味というのが、受入枠は本来は違うという認識でいいということなのですよね。それをちょっと確認したいと求めました。","respondent":"篠田学務課長","answer":"今回、そういった形での対応ですので、本来であれば受入枠を変更するという形になってまいります。通常、そもそも八潮学園は８０人ということで、正式な形での受入枠の変更は行っていないという状況です。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"これは、どれぐらいの年数、そういう対応になりそうですか。そういうのは、どれぐらいの年数になるのか尋ねました。","respondent":"篠田学務課長","answer":"土曜日を工事日として設定して工期を考えてこられたのですけれども、これから先、校舎改築にあたってはかなり工期が延びるということが考えられます。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"年々、抽選校が増えているという状況で、小学校では３年連続抽選になっているのが１２校もあって、中学校もわりとあるということで、選びたくても選べないような状況になっているのかと思うのですが、その点について伺いたいと思います。","respondent":"篠田学務課長","answer":"学校選択の基本的な考え方ですけれども、先ほどもご説明したとおり、基本的には通学区域内のお子さんの数です。現状、こういった形で、学校の抽選校が増えているという状況が続いているのだろうと認識しています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"入りたかったのに入れなかったということで、子どもが傷つくといったこともあるという気がするのですが、そういった抽選で入れなかった子どもへの影響というのはどのようにお考えか尋ねました。","respondent":"篠田学務課長","answer":"学校もそれぞれ対応していくといったこともありますから、そういった意味で、学校選択というのは必要な制度だろうと考えて実施しています。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"選べることが一番大切なのだというお話でしたけれども、今、実際に余裕がなくなってきて、選べなくなってきているということだと思うのです。学校選択制というのはやめるべきだと言ってきましたので、改めて考え直してほしいと求めましたが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"先ほど申し上げたとおり、学校選択制にはきちんとした意義があると思っていますので、現状としては、引き続き、この制度を続けていきたいと考えているところです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"先ほど、抽選して、その結果があって落選された方は、小学校は１月中待機、中学校が２月中待機ということなのですけれど、これは、落選しても、必ずどこかの学校には入れるような仕組みにはなっているということなのか尋ねました。","respondent":"篠田学務課長","answer":"義務教育ですので、まず住所地の学校では必ず受け入れをするという形になります。最終的に、小学校であれば１月末までお待ちいただいて、ご自身の住所地の学校に行っていただくという形になっているものです。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、通学区域の学校には必ず入れると。“残念ながらあなたは通学区域の学校にしか入れません”というような通知をするということでよろしいのか尋ねました。","respondent":"篠田学務課長","answer":"そういった方を全部ひっくるめまして、来年の１月上旬になりますと、就学指定通知というのを各ご家庭に送らせていただきます。それで、待機の間に繰り上がりがあれば、それを変更していくという形になるものです。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問","question":"無抽選受け入れという方もいらっしゃるのかと思うのですけれど、これは希望申請数の「増」というところになるのでしょうか。その辺りの状況も説明を求めました。","respondent":"篠田学務課長","answer":"制度変更に関しましては、要は通学区域が隣り合う学校から選べるようにするという形で変更したのですけれども、この２年間においては。通学区域の変更については、この２か年に関しましては、もともと通学区域であった学校も選べるようにしているという形になってあります。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"ちょっと私の質問がわかりづらかったのかもしれないのですが、希望申請数の「増」というところに入っているということでよろしいのでしょうか。確認をお願いします。","respondent":"篠田学務課長","answer":"そのとおりです。あくまで現在の通学区域と別の学校という形になりますと、そこの数字に計上されているという形になってあります。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"確認なのですけれども。今年度の、どういったお問い合わせなどあったのかというところが気になっていまして、その辺りの状況を教えていただきたいです。","respondent":"篠田学務課長","answer":"来年度以降、こういう形で新しい制度で実施したということで、お母様方のネットワークでもかなり浸透しているというお話は伺っているところです。","id":"exchange-015"},{"speaker":"せお委員","kind":"確認","question":"１点目は確認なのですけれど、特別支援学級などの希望者数というのは、また別の表になるのでしょうか。２点目は、毎年３０名前後のところで、説明を求めました。","respondent":"篠田学務課長","answer":"さまざまな支援をしてきているような状況がありますけれども、支援をしていくといったことも含めまして、対応を考えているところではあります。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"確認なのですけれど、このように申請状況など、途中経過などは出ずに、結果だけ出るということでよろしいのでしょうか。これからの将来などを考えられる学校になると思いますので、それは引き続き、小規模校ならではの施策などを考えていただけるよう要望いたします。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"特別支援学級の途中経過が出ないのかということなのですけれども、ある時期を切って、途中経過についてはお知らせしていないような状況です。最終的には、年度当初、確定した数字をお知らせしたいと考えております。個別に対応する中で、一番ご自宅から近い特別支援学級をお勧めはしておりますが、そこの校長先生も交えて相談させていただいてという実情があります。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つ目は、確認なのですけれど、希望申請の中では特にないのでしょうか。いわゆる、そういった意味での、特別支援学級の学区の変更というのですか、そういうことの可能性について確認したいのですけれど。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"特別支援学級のお問い合わせについてですが、あるいは最初から難しいのかということはなく、個別に対応させていただいているところです。学区の変更が各学校かなりあったので、例えば、今まで１つの小学校で３つぐらいの中学校に分かれてしまうような学区域の区割りがございました。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"例えば９０名という受け入れ枠のところを９９名とか、そういったことを、ぜひご兄弟で一緒に通えるようなことを実現してほしいと求めました。そこは、ご本人、保護者、そして学校にとっても有効なことだと思いますので、個別の相談の際にはご配慮ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"令和２年度 品川区立学校教育職員採用候補者選考状況","agenda":"令和２年度 品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"申込者６１名で、今のところ内定者２名ということで、倍率２０倍というご答弁がありましたけれども、これはかなり狭き門だと思っているのですが、毎年このような状況なのか尋ねました。","respondent":"工藤指導課長","answer":"区固有教員の配置人数に関しましては３０名を目途に行っているところでございまして、現状が２７名ですので、募集人員は３名となっています。ですので、それに対してということで、実際、約２０倍ということで、狭き門という現状ではあります。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、区固有教員の３０名のうち２７名しかいないから、その残りの枠を埋めるために募集したという理解でよろしいのか尋ねました。","respondent":"工藤指導課長","answer":"委員ご指摘のとおりです。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"一応、辞退がどういう理由だったかというのをお聞きしたいのです。その時点でわかるわけがないので難しいのですけれど、対象者をこの段階で９名にしているのはどういう考えなのかというのをお聞きしたい。","respondent":"工藤指導課長","answer":"実際には、第一次選考で合格者が２３名ですが、考え方としては、その約半数を呼ぶと。そういった状況があります。","id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"いい人であれば、よく言われますけれど、よそでも採られると。欠員が１つ出てしまうので、本来の定員をしっかりと確保できるように、今後ともよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから、今、人数として、来年度は１名の枠なのでしょうか。ですから、存在意義というのは大変大きなものだと考えていますので、その点についてもお伺いします。","respondent":"工藤指導課長","answer":"見込みとしては１名というところの欠員がありますけれども、３０名に達した後というのは、またそれは検討していきたいと考えています。少なくとも現状は３０名を目途に、というところで考えているところではあります。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ほかの方と、どちらをどうというわけではありませんけれど、結果としてそうなればいいかと思います。それも学校で随分活躍されているとお聞きしているので、そういった点は、そういった方々に勧奨していただけるといいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-04","title":"品川区子ども読書活動推進計画（素案）およびパブリックコメントの実施","agenda":"品川区子ども読書活動推進計画（素案）およびパブリックコメントの実施","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そういった点がこの計画には盛り込まれているのかというか、そういった面も重視はされていくのか。そこのところを伺いたいと思います。","respondent":"横山品川図書館長","answer":"そちらを、１９ページに図示しました「読書興味」と、この策定委員会の中では捉えました。「読書能力」と位置付けまして、双方をバランスよく身につけていく過程が「育つ」ということで考えていることが、今回の計画の肝です。","id":"exchange-026"},{"speaker":"のだて委員","kind":"提案","question":"そういった提案がされていますけれども、そこの認識というのか、見解について伺いたいと思います。これは２９ページにありますが、どういった形で、そういったところを伺えればと思いますとの意見を述べました。","respondent":"横山品川図書館長","answer":"主にこれは読書に困難さを感じるお子さんに向けての対応ということで考えているところで、実施している、もしくは考えている事業です。最終的には個別対応になると思うので、読書相談であるとか支援・フォローというような形で補っていきたいと考えています。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"それはしっかりと周知していっていただいて、誰もが本を読んでいけるというような環境整備をしてほしいと求めました。なかなか読めない子どもたちへの支援というのですか、そういったことも必要だと思うのですけれども、その点ではどのようにお考えか尋ねました。","respondent":"横山品川図書館長","answer":"読書へ困難さを抱えたお子さんへの対応と同じように、一般的な、非常に大事な取り組みだと思っています。高校生、一人ひとりにフォローが入ってくるような状況をつくり出すことが、これからの役割かと考えているところです。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、言いましたこともぜひ重視していただいて、子どもの読書が進むようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは図書館だけの意思ではなかなか難しいと思うのですけれど、それもやはり読書の推進に関連していると思うので、そこの点が１つ。再開発するときに、そういった施設をということを、教育委員会として発言する機会などはあるのか尋ねました。","respondent":"横山品川図書館長","answer":"今のところは、また区内の施設で団体貸出やグループ貸出という形での触れ合いの中で、少しずつ拠点を増やしていきたいと考えています。地域全体でそれを叶えられるような形に、区全体でできるように、これから進めていきたいと考えています。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"意見","question":"図書館としても、機会を見つけて、設置についてはうまくいくようにしてほしいと求めました。広町に関しては、そういったことを心に思っていただいているということがわかりましたので、ぜひ実現することを希望しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"のだて委員","kind":"意見","question":"先ほど聞き忘れました。この期間を決定した理由と、最低でも１か月ぐらいあったほうがいいのではないかと思うのですが、いかがでしょうとの意見を述べました。","respondent":"横山品川図書館長","answer":"パブリックコメントの期間のことですが、大体どの計画でも２週間から１か月ぐらいの期間をとっております。２週間とるのがぎりぎりという形になってしまいまして、このような期間で、最低限というような形で２週間設定させていただいたところです。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"会議との関係でこうなったというお話でしたが、後ろが決まってしまっているということだと思うのですけれど、前が延びるということはできなかったのか尋ねました。","respondent":"横山品川図書館長","answer":"２週間を目途として設定しているところがあったので、前というのがなかなか考えられなかったのと、パブリックコメントの期間自体は２週間で十分かという考えがございました。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろな専門家がワークショップをやって、話、意見を聞いているということでしたけれども、やはりこのパブリックコメントで初めて知る方もいらっしゃるので、ぜひパブリックコメントの期間を最低でも１か月設けるようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"せお委員","kind":"質問","question":"１点だけ失礼します。５９ページに、策定委員会の名簿があるのですけれど、新しい５年間の計画では、こちらの委員の方々は変わらないということか尋ねました。","respondent":"横山品川図書館長","answer":"こちらの名簿に載っている委員につきましては、あくまでも推進計画をつくるための委員の方で、これを運営するにあたっては、図書館サイドが実施主体として、各所管と連絡をとりながらやっていくような形になるかと思います。","id":"exchange-035"},{"speaker":"せお委員","kind":"質問","question":"では、策定委員会はこちらのメンバーで、これから開かれることはないということか尋ねました。","respondent":"横山品川図書館長","answer":"こちらは、５９ページにありますように策定するための委員会なので、令和元年６月１日から令和２年３月３１日までの期間の設定になっております。ですので、令和２年４月１日からの実行期間については、図書館が運営主体として各所と連絡を取り合って運営します。","id":"exchange-036"},{"speaker":"せお委員","kind":"質問","question":"こちらの委員の方を拝見していると、読むことに困難を抱えている当事者の方などはいらっしゃらないかなと思うのですが、この点はいかがか尋ねました。","respondent":"横山品川図書館長","answer":"学校地域コーディネーターの方であるとか、また学校長の先生方は、日ごろ児童・生徒と接しています。教育総合支援センター長にもオブザーバーとして参加していただいて、特別支援のこと、ほかについて教えていただくような機会もございました。","id":"exchange-037"},{"speaker":"せお委員","kind":"意見","question":"そういう困難を抱えている方のニーズを把握するには、やはり当事者の方を一人でも入れていただけると相互理解がすごく進むと思います。パブリックコメントの実施もすごくいい企画だと思っていますので、そういった委員の方を選ぶ際にも配慮いただけたらと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"４３ページのまちライブラリーのところなのですけれども、品川区は今現在、まちライブラリーはあるのでしょうか。おはなし会ですか、もしわかっているのであれば教えていただきたいのと、もし詳細がわかりましたら説明を求めました。","respondent":"横山品川図書館長","answer":"ですので、そういう取り組みをこれからも進めていきたいと考えています。例えば子どものワークショップで出ていたのですけれど、そういういろいろな可能性を含めて、これから検討していきたいと考えます。","id":"exchange-039"},{"speaker":"横山委員","kind":"提案","question":"４３ページにもありますけれど、やはりどうしてもあるのかということで、進めていただいているのかと思うのです。各学校での委員会等で出ている意見や提案など、そういったところも、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"これから継続的に提案制度というか、集まる会をつくって、図書館の施策も一緒に考えてほしいというのをしていきたいと思っています。当事者が考えるのが一番有効なやり方だというところは認識しておりますので、そういう機会をつくりたいですし、もう少し進んで。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"鍵がかかっているところもあるとか、そういった話もありましたけれども、今後は開館していって、有効活用していこうというお考えなのでしょうか。学校図書館についてどのようなお考えなのか、説明を求めました。","respondent":"横山品川図書館長","answer":"委員ご指摘のとおり、学校図書館は学校の中で非常に重要な施設だと認識しております。本を読むだけではなく、いろいろな情報を活用して調べたり考えたり協議したりするような場に、そちらに向けての支援を進めていきたいと考えています。","id":"exchange-041"}]},{"id":"topic-05","title":"子どもの食の支援事業","agenda":"子どもの食の支援事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１８歳未満のお子さんをもっている家庭なので、持っていない家庭があった場合の申請方法、そういった対応について伺いたいと思います。実態把握のところで、アンケートを実施するということなのですが、どういった形でやられるのか、今の検討状況を伺えればと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"ご連絡いただければ申請フォームと同様のものを書類としてお送りいたしまして、それを申し込んでいただければと考えています。最終検討している段階ですけれども、例えば就労支援、学習支援が必要な方に対して区の施策を展開していきたいと考えておりますので。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"アンケートのほうでは、対象というのですか、ひとり親家庭、今回通知したところということになるのか。その辺りを伺いたいです。","respondent":"三ッ橋子ども家庭支援課長","answer":"電子申請フォームの中でも検討していますけれども、実際の申請のときにも、その辺りもさまざまなご意見をいただきたいと思っています。食を届けたときにもアンケートを実施していくと考えております。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"最初に、寄附はどのぐらいの、どういう人たちか。それと、金額的には大体お１人で平均どのぐらいのものが多いのかというようなことも伺いたいと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"区内の方は８０万円強となっております。それから、１人の平均の金額なのですが、さまざまですので、１人平均幾らということは差し控えします。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"１人当たり、人数の、抽選になる限界の決め方というのはどういう決め方なのでしょうか。予定より多かったら少し枠を広げましょうか、といった余地を考えているのか、その辺りの考え方をお伺いしたいと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"区外の方は７２名、区内の方は３３名です。応募された方に対して食品配送をしていきたいのですけれども、確かに限界がありますので、応募状況によって勘案したいと思います。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"“こういうものが欲しい”という注文みたいな部分があるのかどうか。仕入れなどというのは、どういうふうにかけるのかなどというところで、その辺りの食品の需要と供給の関係みたいなところをお伺いしたいと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"書かせていただいたように、主食を中心に嗜好品ということを考えております。食品の調達は、今、区内企業を考えておりまして、そこと最終調整しています。","id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、子ども食堂に１００万円ということなのですが、こちらはどのように使っていくのかというところ。今、検討はしていただいているかと思うのですけれども、その辺り、詳細を説明するよう求めました。","respondent":"三ッ橋子ども家庭支援課長","answer":"子ども食堂に１００万円という部分ですけれども、しながわ子ども食堂ネットワーク事務局と相談していきながら考えてまいります。食の支援に困っている方というのが一番基本にありますので、「食の支援に困っていますか」と聞いて、その部分を中心に考えていきたいと思っています。","id":"exchange-047"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"たしか来年、寄附していただいた方に対して何かしらの、“もし次もあればお願いします”みたいなアプローチができているのかを教えていただきたい。そうすると、結構な量が送れるのではないかと思うのですけれども、これは別に賞味期限などは大丈夫ということでいいのか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"そのときに、「来年度以降も実施する場合には、よろしくお願いします」という部分は伝えていく予定です。食品の配送を３月中と考えておりますので、すぐではないものを、という部分は伝えてまいります。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"確認","question":"１つだけ。これは今、最終的にふるさとチョイスに支払う手数料というのでしょうか、そういうものはお幾らになるのか確認いたします。","respondent":"三ッ橋子ども家庭支援課長","answer":"ふるさとチョイスへの手数料ですけれども、１０％です。","id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"手数料、わかりました。それで、４００万円以上集まったので、事業への活用を速やかに行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]},{"id":"topic-06","title":"ひとり親家庭住宅入居支援事業","agenda":"ひとり親家庭住宅入居支援事業","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"チラシが、どういった形でお知らせされていくのかということと、今回の事業について予算額というのはどのぐらいになるのでしょうか。できるだけ多くの方に支援していっていただきたいと思うのですけれども、伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"ひとり親家庭住宅入居支援事業についての説明もいたしますけれども、どういうところを探しているとか、本当に基本的な住宅相談をいたします。それから、住宅相談会について、講師派遣料１８万円と、予算上はトータルで８８万円を予算計上しております。","id":"exchange-051"},{"speaker":"のだて委員","kind":"確認","question":"そういうものが受けられないわけではないというところの確認と、初回保証料は７件ということで、実績などは多分ないのですよね。７件の根拠というのですか、そこのところを伺いたいのと、保証額というのは大体１０万円以内でおさまってくるのかというところも伺いたいと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"この住宅入居支援事業に対して、保証料の部分の助成は相談した上で、例えば窓口等々相談した上で助成してまいります。例えば家賃が７万円でしたら３万５,０００円から７万円という形を想定して、１０万円といたしました。","id":"exchange-052"}]},{"id":"topic-07","title":"西五反田保育園病後児保育室の改築","agenda":"西五反田保育園病後児保育室の改築","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"「２方向避難の確保」というのがあるのですが、今までは確保されていなかったということなのか、そこのところを伺いたいと思います。安全面への配慮からのレイアウト変更というところも、大体どういった変更なのかというところを伺えればと思います。","respondent":"吉田保育施設調整担当課長","answer":"ただし、改築するにあたりましては、２方向避難の確保等が必要になりますので、今回、既存不適格の部分を是正する措置をとった次第です。子どもが近寄れないような形での柵を設けたり、子ども向けの新しい手洗い場だとか、そういうところの増設になります。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、２方向避難のところは、平成１２年に違う施設として開設されて、どこかのタイミングで病後児保育室に変わって、そこで既存不適格になって、今回改築するにあたって基準を満たすようにしていくということでよろしいのか、そこの確認をさせてほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"言い方は乳幼児健康支援一時預かりとなりますけれども、当時から病後児保育室ということで続けてまいりました。保育室の基準の変更とかが多々ございまして、現在では２方向避難は必須となっておりますので、基準を満たすように変更したです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"それはぜひ安全確保のためにやっていってほしいと求めました。これは関連してなのですが、ほかの保育園などで、そういった２方向避難の既存不適格の園というのはあるのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"保育室の全園において既存不適格があるかどうか、今、資料が手持ちにないところです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"今わからないということで、あるかないかもわからないということですか。一時休室にするということなので、そこは周知をしっかりとしていただいて、利用されていた方が困らないようにしてほしいと求めました。","respondent":"佐藤保育課長","answer":"病後児保育室の２方向避難の関係ですが、２施設あるのですけれども、２方向避難は確保されています。西五反田保育園に関しましては、別の施設を使っている関係で、そういった状況であるということです。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"やはりちょっと古くて、外から見ると、ちょっと暗い感じがあります。病後児なので、あまり明るくてもあれですけれども、その辺りのレイアウトも配慮して改築してほしいと求めましたが、いかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"病児保育に向けての変更です。内装、明るさ等につきましては、必要な明るさ等を確保しながら進めてまいりたいと考えています。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"議会の中でも病児保育の必要性が議論されて、区にも要望させていただいていると思いますので、その方向でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]},{"id":"topic-08","title":"品川区第二期子ども・子育て支援事業計画（素案）","agenda":"品川区第二期子ども・子育て支援事業計画（素案）","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"ひろまち保育園の閉園に伴う定員などもあると思うのですが、そういったところも含めて検討されているのかというところを伺いたい。令和２年度から令和３年度になるときに、５歳児と２歳児のところが結構、何かあれば伺えればと思います。","respondent":"吉田保育施設調整担当課長","answer":"量の見込みを立てる際に、国からの算出の考え方というのが出ております。令和２年、３年の乳幼児人口が増えているところにつきましては、その辺りを踏まえて人数が増えているところです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"令和２年度から令和３年度のところで、何か要因があるのかというところで伺ったのですが、もう一度ご答弁ほしいと求めました。どう考えたらいいのかというのはあるのですけれど、施策としてこれでいいのかと思うのですが、区でどう考えていらっしゃるのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"それから、量の見込みに対して、確保方策は努力目標ですので、そちらを確保することによって、必要な量に対して確保を頑張ります。それなので、過不足はゼロになるという考え方です。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"していくべきだと思うのですけれども、そこのところを伺いたいと思います。すまいるスクールのところで伺ったのですけれども、確保するというのが、全児童数を確保する。","respondent":"吉田保育施設調整担当課長","answer":"国から指示を受けた、国の計算方法に基づいてやっているところもありますので、それに合わせて計算は進めてまいります。量の見込みの全児童数というのは、利用する方の全児童数ということで、その下がその内訳となっているところです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"わかりました。区の方針というのですか、含めてぜひ確保していっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"子ども・子育て支援事業計画につきましては、昨年９月、国から、量の見込み等の算出のやり方等、マニュアルが出ております。そのため、それに沿った形で、区も対応しています。","id":"exchange-062"},{"speaker":"のだて委員","kind":"確認","question":"国のやり方に沿っているということで。そうしたら、これは隠れ待機児童も入っているのかどうか、それを確認します。","respondent":"吉田保育施設調整担当課長","answer":"隠れ待機児童の捉え方があるとは思うのですけれど、認証保育所などは、２９ページ、３０ページで数値として、１項目としては周知はしています。","id":"exchange-063"},{"speaker":"のだて委員","kind":"意見","question":"今の答弁は、入っているという話だったのか、よくわからなかったのですが、やはり希望した子どもたちがしっかりと入っていけるということが重要だと思いますので、そういった対応をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"筒井委員","kind":"質問","question":"どういう基準で選ばれているのかということと、あと公募区民の方が３名いらっしゃいますけれども、この３名になったのでしょうか。そうした委員のことについて示すよう求めました。","respondent":"吉田保育施設調整担当課長","answer":"それから公募委員の応募状況ですけれども、今年の４月から、新しい委員、第４期の委員に切り替わっております。第４期の選出にあたりましては、公募につきましては応募が４名ございまして、そのうち３名を選んだところです。","id":"exchange-065"},{"speaker":"筒井委員","kind":"意見","question":"それとも区独自で、こういうふうにしようということで判断されたのか、どちらなのでしょうとの意見を述べました。","respondent":"吉田保育施設調整担当課長","answer":"子ども・子育て支援法で、それから新しい保育園を建てたりするような場合、意見を聞く場を設けるという指示があります。必要な数、整えまして、こちらの会議体とした次第です。","id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"では、具体的にどういう方を呼ぶかというのは、区の裁量ということでよろしいのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"先ほど申し上げました学識経験者であるとか、事業に従事する者というところで大きく分類しまして、その中で必要な、最大の効果があるような形での人選をしています。","id":"exchange-067"},{"speaker":"塚本委員","kind":"確認","question":"最初に確認ですけれど、２歳児・保育認定ですけれど、その他と。これは、下の内訳の３段、令和２年度から令和６年度まで、全部同じ数字になっているのはこれでいいのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"その他のところが今後増えていくかどうかというのが見込めなかったところなので、今のところは令和２年度の形で、そのまま横引きしてあるところです。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"増えていく見込みが見通せなかったというのは、いまいち理解し得ないけれど、確保方策としては増えるわけですよね。量の見込みも増えるわけで、それでなぜ内訳が増えないのかというのが、整合性がないように見えるのですけれど、そういうことではないのかどうかとの意見を述べました。","respondent":"吉田保育施設調整担当課長","answer":"３号認定の教育・保育施設につきましては、令和２年度以降の数値が増えていくのが正しい形になります。３０ページにあります、２２ページの数字は至急、訂正いたします。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"増えない。要するに、教育・保育施設で、そういう方針をとっているということの理由をお聞かせいただきたいというのが１つです。","respondent":"大澤保育支援課長","answer":"３歳児から別の保育園に行けるようにはしていますけれども、０歳から５歳で一貫した保育をということで、希望者が減っているのが現状です。今後、地域型保育事業を増設する予定はございませんので、数値としてもゼロを見込んでおります。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"お伺いしたいのは、１０月に一応、その辺りのことを加味した形での調査というのがなされているのかというのをお聞きしたいと思います。その上で、そもそも保育士の確保ということが大前提ではあると思うのですけれど、その辺りについての現状での認識をお聞かせほしいと求めました。","respondent":"吉田保育施設調整担当課長、大澤保育支援課長","answer":"ニーズ調査ですので、ここにどれだけ反映されているかという意味では、実際に無償化が始まってからの意識とはまた大分異なるものと認識しております。もう一度、保育の量等の見直し等は行う必要もあるだろうと… 保育士の処遇改善ですけれども、この間、区としては、賃金改善と宿舎借り上げ、インフルエンザ助成等をやっているところです。そういった保育士の処遇改善も、今後、継続していくしかないだろうとは思っています。","id":"exchange-071"},{"speaker":"横山委員","kind":"質問","question":"幾つかお伺いしてまいります。６０ページのしながわネウボラネットワークの部分なのですけれども、どういう支援をお考えなのか、お聞かせいただけたらと思いました。","respondent":"吉田保育施設調整担当課長、崎村児童相談担当課長","answer":"申しわけございません。しながわネウボラネットワークの1)、それから3)の産後ケア事業につきましては、細かい数値等は持ち合わせていないところです。産後の育児支援の利用助成なのですけれども、１０月の段階でもう昨年度に近いぐらいの数字になっておりまして、拡充が必要な事業だと捉えております。","id":"exchange-072"},{"speaker":"横山委員","kind":"確認","question":"所管外のところを聞いてしまったのですけれど、申しわけありません。５８ページなのですけれども、どういった時期、確認したいと求めました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"子ども・子育て支援法につきましては大都市特例という規定はございませんので、児童相談所の設置をもって、こちらの事業計画を変更するというのは。そちらとの兼ね合いを見ながら考えていきたいと考えています。","id":"exchange-073"},{"speaker":"高橋（し）委員","kind":"質問","question":"教育・保育施設を増やしていくという確保方策だと理解させていただいてよろしいでしょうかということが１つ。オアシスルームの利用者が非常に多いということなのですけれども、そちらの利用実績の上昇に関する今後の対応はどのようにお考えか尋ねました。","respondent":"吉田保育施設調整担当課長、大澤保育支援課長","answer":"委員ご指摘のとおり、教育・保育施設につきましては、今後、増えていく方向で、数値は書き改めるのと、パブリックコメントにおいての資料も差し替えます。 オアシスルームにつきましては、今後、増設の方向で検討してまいります。","id":"exchange-074"}]},{"id":"topic-09","title":"ぷりすくーる西五反田","agenda":"ぷりすくーる西五反田","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、認定こども園化することによって、どういったことが変わってくるのかということを伺いたいのと、今、いろいろと調整中ということでしたが、職員の方や、あとは子どもや保護者の方にとっての変更点というか、そこを伺えればと思います。","respondent":"吉田保育施設調整担当課長","answer":"それから、利用者にとっての変更点というのは、今まではＮＰＯでございましたが、今度は社会福祉法人が運用母体となります。教育方針につきましても、現在のぷりすくーる西五反田の教育方針が、全体を含めて調整しています。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、子どもや保護者の方への変更点というのは特にないということでいいのかということと、ＮＰＯから社会福祉法人に事業を移行するということで、それは職員も一緒に移動するということなのか、そこのところをお伺いいたします。","respondent":"吉田保育施設調整担当課長","answer":"子どもと保護者については、今までと大きく変更するとなると、名前です。１年間とかをかけてやらなければならないところもありますので、それで質を維持して次につなげていきたいと、今のところ進めているところです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"移行して大丈夫なのかと言うとあれですけれど、保育士は残るから問題はないのかどうか。そこのところを伺いたいのと、認定こども園化されることで、保育料とか、そういった面の変更もないということなのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"そういう意味での現行の質が落ちるとは考えていないところと、保育士等の確保につきましては、現行よりもかなり有利になるものと考えております。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。社会福祉法人立にしていくというスケジュールだと思うのですけれど、そうした理由、経緯を伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"社会福祉法人になったからといって、すぐに認定こども園となるというわけでは、今のところも予定しておりません。そのため、２０２４年までをかけて、その間、必要なところを、時間をかけて調整していくというところのスケジュールを組んでいるところです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"課題はほかにもあるというお話だったのですが、その課題の解決の見通しというのですか、解決できそうなのかというところを伺いたい。","respondent":"吉田保育施設調整担当課長","answer":"必要な対応をしていくことで、解決に導けていけたらと考えておりますが、法人の話になります。そこのところは社会福祉法人の考え方等もあると思いますので、私からは差し控えたいと思います。","id":"exchange-079"},{"speaker":"塚本委員","kind":"確認","question":"１、２歳に関して言えば、品川区の保育料が所得に応じて決まっているじゃないですか。保育料というのは、他の認可施設と同じように決められてくるという認識でいいのではないかと思うのですけれど、その確認をお願いします。","respondent":"吉田保育施設調整担当課長","answer":"１０月からの無償化のところにおきまして、無償化の対象になっているところもありますので、その制度が続いている限りはそのような対応になります。現在はそのような状況です。","id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"どういうふうな幼児教育というか、そういうものを目指していくのかというようなことの検討というのは、どのような形でされていくのか。そのようなことについて、現状で見えている部分というものがあれば説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"それによって、ぷりすくーる西五反田の現行の教育方針や、その他いろいろな事業、やってきたことを引き継げるような形のものを、今、考えております。発展的な意味で、よりよい認定こども園化を目指していければと、今は予定しています。","id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"質問","question":"「社会福祉法人化について」の２行目のところで、この部分の記述がどうなのかということと、文脈的にあれかと思って。ここの１文は、まず、そこはどうか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"ＮＰＯ法人子育て品川につきましては、区から委託されて、ぷりすくーる西五反田を運営しているということで、ＮＰＯとしての自主事業がないのです。それがあるので、このＮＰＯがそのまま社会福祉法人になれないというところの説明が、この資料の２になります。","id":"exchange-082"},{"speaker":"高橋（し）委員","kind":"質問","question":"ＮＰＯが今後２年、その後、社会福祉法人福栄会にどういう形で移るのか。その後、法人立になるということは、区立ではなくなるという意味でおっしゃったのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"２０２４年になりますと、今の予定では、そこで認定こども園化を目指します。それで、今度は社会福祉法人立の認定こども園と考えておりますので、ここで初めて社会福祉法人立の施設となる予定です。","id":"exchange-083"},{"speaker":"高橋（し）委員","kind":"質問","question":"３年分の指定管理に関しての、何というのですか、そういった補償についての話は出てくるのでしょうか。どこまで区がそれについて確約というのでしょうか、指定管理になるかどうかが仮定の話で少し変な話ですけれど、その辺りのことも伺います。","respondent":"吉田保育施設調整担当課長","answer":"５年間から２年間になってＮＰＯに損害がということであるのですけれども、実際、ＮＰＯと社会福祉法人で話をしていただいているところです。確かに今までもしてまいりましたので、主体的にはＮＰＯと社会福祉法人の間の話であると、区は認識しています。","id":"exchange-084"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"田中議員の体罰の質問のところで、児童をたたいたり、廊下に立たせたりという事例があるということで、そういった声が届いている中で、今後、調査などは行っていくのか、また、そういった事例を区でつかんでいるのか、伺いたいと思います。","respondent":"工藤指導課長","answer":"いつ、どの学校で起きたのかという情報がない段階ですので、それについては把握しているかどうかという判別ができないと考えるところです。一般質問の中で出された事例に関しましては、現在、各学校に対して調査を行っているところです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"確認","question":"判別ができないというお話だったのですけれど、この間の体罰に関する報告の中で、たたくとか、廊下に立たせるといった事例というのは報告されていないのかどうかを確認します。","respondent":"工藤指導課長","answer":"当該行為が行われた場所的および時間的環境、懲戒の態様等、これら諸条件を総合的に考えた上で判断・判別をするということになってあります。それは、例えば、これまで、いつ、そういうことが私どもに報告があったのかということも含めて調査をしています。","id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/211588?Template=document&Id=4988#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":61273,"voices":246}},{"id":"r01-20191203-5","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"総務委員会","time":"午前１０時００分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"品川区長期基本計画の策定状況","agenda":"品川区長期基本計画の策定状況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"質問ですけれども、パブリックコメントについては１８２人の方からご意見が寄せられたわけですから、その辺について質問をしたいと思います。品川区と区民との、また区民同士が意見を交わすことをやはり踏むべきではないかと思うのですけれども、その辺についてもお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"区の考え方につきましては、これをもって回答といいますか、区の考え方を示すということで行わせていただきたいと思ってあります。これまで８回、議会の方々も含めてご議論いただいたと私どもとしては認識をしているところでございまして、その答申を受けて。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"連絡先がわかる人にとっては返事をすべきだと思いますので、この点、もう一度伺いたいと思います。区もこうやって区の意見を述べているわけですから、返事をすべきだと思いますので、改めて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"区の考え方をお示しさせていただきたいと思ってありますので、考え方につきましては、こういった形で行わせていただければと思ってあります。ただ、そういったことに関しましては、トータルとしてはこの形をホームページに出すということで行わせていただければと思ってあります。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"要望なんですけれども、スケジュールの段階で住民説明会の日程を今後は取り入れてほしいと強く要望したいですし、ちょっと見解を伺いたいと思います。皆さんが参加できるような形になったのかというところの確認をさせてほしいのと、冊子として置かれるのかという部分についても確認したいと求めました。","respondent":"柏原企画調整課長","answer":"全体でこれも１年間かけて、内部の検討活動に２年以上かけてやっているところもございまして、その間で説明会なんかを入れるという。検討しています、これを実現化するための実施計画であったり、各個々の部分で検討をしていきたいと思っています。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"確認をさせてほしいと求めました。ヤングケアラーの部分は具体的施策に取り入れてほしいということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう分析ですかと言われたときに、区の返答としては、一生懸命やっているのはわかります。日本全体で見れば人口減少ですから、不安要素があるかなと思っているのですが、その辺のご見解をお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"前回の計画は１０年の計画で、ただ、この中身についての見直しはタイミングを見計らいながら検討することになってこようかと思いますので。区の考え方を大きくこう表現させていただいてありますけれども、どういう表記の仕方がいいのかは、もう少し検討が必要だと思ってあります。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、実施計画もこれからいろいろ考えられてつくられていくと思うのですけれども、常に１年ごとに見直しを図りながら、事業を見ていく。福祉なのか、さらに魅力が明確にアプローチできるのかなと思いますので、それを今後実施に当たっては検討していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"でもやりようによってはさまざまなもっと大勢の人の意見が聞ける、聞きやすいそういう品川区に私はなってほしいと思います。本来ならやはり評価してほしい施策もありますし、今までやってきた事業で、こういうことはよかったよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-02","title":"台風１９号被害に伴う山北町、早川町への見舞金","agenda":"台風１９号被害に伴う山北町、早川町への見舞金","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"見舞金にかかわって、台風１９号は本当に各地に被害があって、品川区から職員の派遣はどういう状況なのかあわせてご報告いただけますかとの意見を述べました。","respondent":"黒田人事課長","answer":"１９号の派遣ですけれども、どの団体がどこの自治体を支援するというのを決めた中で、東京都は千葉県君津市を対口支援団体として決められましたので。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"今、どういう状況なのかなと思うのです。それはいかがか尋ねました。","respondent":"立川総務課長","answer":"被害状況の説明をもうちょっと詳しくお話しいたしますと、町営のオートキャンプ場のふれあいビレッジに土砂が流入いたしまして、これは復旧未定です。それまでは遊歩道を通るようにしまして、人力で町の職員が食料等を届けたりしていたです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"まだまだ復旧はしていない状況だなというのがわかりました。できないとか、何かいろいろ報告しないといけないと思うのですが、それはいかがか尋ねました。","respondent":"立川総務課長","answer":"こちらは地域活動課のほうで、ふれあい交流、ふるさと交流ということで事業を実施しておりますので、詳しいことはまだ聞いていないところですので、こういうご質問があったということで所管課のほうに伝えたいと思います。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"今、品川区でも災害見舞金というのをそれぞれ住民の皆様に各個別に支給する事業があると思うのですが、その辺はどのぐらい充実されているのですか。火災とか災害とか、交通事故やさまざまあると思うのですが、ちょっと参考のために説明を求めました。","respondent":"立川総務課長","answer":"所管が違いますので、お答えは控えします。","id":"exchange-011"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"以前から指摘をしてきましたが、ちょっと矛盾するけれども、一方でさまざまな工夫もしながら取り組んでいただきたいと考えています。質問だけお願いいたします。","respondent":"伊東税務課長","answer":"１,０００種類とかいうようなキャッチコピーもありましたが、そういうもので、ありとあらゆるものがあるという。やはり土地柄、ネームバリューがあるところの物に関してはやはり人気があるというところで、多くの寄附が集中しているという傾向です。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"各所管課の取組みの状況をもしご説明できるようでしたらしてほしいと求めました。もう１点が、今年度の流出額の見込み額がこれだけ増えている理由を教えていただければと思うのですけれども。","respondent":"伊東税務課長","answer":"今年度の見込みのところで、２３億円ほどが控除という形で流出しているという状況ですので、ほぼほぼこの数字は今年度の流出額と言えるところです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"それと区民に対して大変な負荷がかかってくるのだと思うのですが、これはどうなのですか。ご意見をちょっと説明を求めました。","respondent":"伊東税務課長","answer":"可能な部分で地場産品として品物というのもなかなか考えている部分もありますので、少しやってみたいなという思いを持っているところです。３割以下ですけれども、以前よりは少し単価的な部分は見直しをして、やれる範囲でやっていきたいなと思っているところです。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうしないと、これは２３区、皆さんおそらく困ってしまうと思うので何か。何とかそっちの対策、何かいい方法がありましたら、私は２３区で区長会でも副区長会でも考えてほしいと求めました。","respondent":"桑村副区長","answer":"全国連携ですとか、先ほどのいわゆる山北町あるいは早川町にそういう意味では支援をするという意味で、都会がそういう意味で全国から支援を受けて。そういう事業の支援あるいは区が特別に狙っているような仕事、むしろ事業支援をもっと打ち出す、もう１つは全国連携を。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"幾つか質問なのですけれども、２９年度から３０年度は非常に品川区へのふるさと納税額が大きくプラスされているのです。なぜ多くなったのかなというのを１つお聞きしたいと思います。","respondent":"伊東税務課長","answer":"３０年度大きく伸びているところの理由としては、３０年度は品川区水辺千本桜計画があったというのと、あと我々のほうでシナモロールのぬいぐるみをつくって、それがファンに受け入れられたというところで、伸びているところです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"どういう計算になっているのでしょうか。それも含めるともうちょっと高く流出額というか経費も含めるともうちょっと影響の金額は多くなるのかなと思うのですが、いかがか尋ねました。","respondent":"伊東税務課長","answer":"返礼品は今、品川区に去年でも９７１万円ほどもらっているという中では、単純に考えれば３割以内の返礼品を出しているということです。純粋にそれが全部一般財源で使えているということではないというのははっきり言えるところです。","id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"だから返礼品ではなくて本来のふるさと納税という考え方からいうと、やはり事業支援をしてほしいという思いがあるわけです。税務課が悪いわけではなくて、担当とか役割とすると、ちょっと所管が違うのではないのかなと思うのですがとの意見を述べました。","respondent":"榎本総務部長","answer":"事業支援ということは各事業が、今もう全庁の職員はわかっていますので、こういういろいろなメニューを考えるのは各部で検討していますので。しばらくはそういった形でできるのかなと思います。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう結果だったのかとかという分析とかいろいろ出てくると思うのですけれども、それは今後、検討していただきたいなと思っています。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"どう今後抑制をしていくことができるのか、どういう取り組みが考えられるのか、考えがあったら教えてほしいと求めました。こういうふうにお金が出ていっていますということが、どう今後していこうと考えているのかを説明するよう求めました。","respondent":"伊東税務課長","answer":"こちらからお願いというのもなかなか言葉として発することは難しいというか、できないところですので、なかなか具体的な策は思いつかないところです。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区民でこれだけ２３億円が出ていっているわけですから、今後、そこをもう少しいろいろ研究しないといけないのだなと改めて思っているところです。今、何かほかの自治体との連携とかというのが可能なのかどうかといったことができるのかどうかがちょっとわかれば教えていただきたいです。","respondent":"伊東税務課長","answer":"もう１点、今回の改正で明確に示されてしまったところで、そうするとなかなか自区民に対してのＰＲというのは難しいところです。今後、全庁的に考えていければというところです。","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問","question":"全国連携みたいなところで、広域のガバメントクラウドファンディングというのも一方であるのかなと思って、ちょっと質問させていただきました。そういった持っているものを使ってのクラウドファンディングではないですけれども、ふるさと納税の何か考えとかがあれば説明を求めました。","respondent":"伊東税務課長","answer":"考えているところで、何かもう一つつけ加えられるものがあれば、ちょっと魅力的になるのかなという思いを持っているところです。それをまさに今後、来年度に向けて、検討をしていき、ＰＲできれば寄附に結びつくかなというところです。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"この間、なかなかそれがやっとこういう形でこの６月１日の改正で少し是正されてきたのかなという印象があります。よく税収がなぜ増えているのですかと言われるときに、この２３億円という金額が、どの程度の影響があるのかまず教えてほしいと求めました。","respondent":"品川財政課長","answer":"どう考えているかというところは、かなりやはり痛いところではあるのですが、なかなか区民の方に伝えにくい部分もあるかなというところがあります。返礼品の部分もどのようにしてこれから獲得していくかというところも、やはり考えていかなければいけないかなと考えています。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問","question":"だからそこのところの見え方というのですか。できないので、ちょっとわからない部分もあるので、そのあたりを教えてほしいと求めました。","respondent":"伊東税務課長","answer":"どれだけ控除されているかというのは、大体６月ぐらいに決定通知が普通徴収ですと送られるわけですけれども、その中に控除という形として金額が載る。前の年に寄附をしていたというところで、納付額が控除されますので、少ない金額での納付になるということです。","id":"exchange-024"},{"speaker":"つる副委員長","kind":"質問・要望","question":"私も事前に細かく確認をしてから質問させていただければよかったのですけれども、翌年度の住民税の税収が減額になるわけではないですか。やはり１つの税務課だけではない形で、そのあたりは令和２年度の中で、いろいろやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993969?Template=document&Id=2154#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":35177,"voices":71}},{"id":"r01-20191205-14","meetingId":"r01-cm12","date":"2019年12月5日","dateIso":"2019-12-05","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"」という感じを私は受けているのですが、改めて間接にではなく直接お伺いしておきたいのですけれども、庁舎を建て替えるという話は。要するに決まったことなのかということを、前提としてはっきり直接お伺いしておきたいのですけれども、お願いします。","respondent":"立木経理課長","answer":"今年度６月、それから８月の行財政改革特別委員会でもご説明させていただいたとおり、最終的にはこれが決定するという形になろうかと思います。今の段階では建て替え候補地を決めまして、建て替えの方向に向かって検討を進めていく段階です。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"よくわからなかったのですが、建て替えは決まったということなのですか。決まっていないということなのか尋ねました。","respondent":"榎本総務部長","answer":"厳密に言えば決まっていないということです。Ｄ案を中心に検討を進めていくこととしたい、協議ですので、そういった意味での「決まったか」と言われると「まだ決まっていない」です。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"決まっていないけれども協議は進めるのですか。それがまたよくわからないのですが。","respondent":"立木経理課長","answer":"４つの候補地の中でその再編を前提としたとしても、それを進めるに当たって、ＪＲ東日本との再編についての協議が必要になります。それが整った段階で正式にそちらに建て替えができるのではないかという決定をとれるかです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"庁舎建て替えについては決まっていないけれども、土地を交換する調整についてはＪＲと協議をするということは決まっているということなのか尋ねました。","respondent":"立木経理課長","answer":"庁舎のための土地再編ということではなく、あくまでも広町地区のということで聞いております。そうした中で協議が整えば、区も一定程度広い土地が使えるということで庁舎の候補地として挙げさせていただいたところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"もう一度整理しますと、庁舎の建て替えは決まっていないけれども、土地の再編は決まっているということなのか尋ねました。","respondent":"立木経理課長","answer":"これは、すみません、所管は建設委員会のほうになろうかと思いますが、広町地区で一定程度まちづくりが進んでいる中で、それぞれ土地を有効利用するとの観点から再編の協議を進めていると聞いてあります。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"ですから、土地の再編については決まっているということなのですね。","respondent":"榎本総務部長","answer":"それを今、再編について協議をしているということなので、協議の結果、再編はだめだと言われれば整わないです。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"では、土地の再編もまだわからないという理解でいいですね。ですから、これを十分に煮詰めてから話し合うべきではなかったのかと私は思っておりますけれども、その点はいかがか尋ねました。","respondent":"立木経理課長","answer":"まさに委員がおっしゃったとおり、これから機能検討を進めていくに当たりましては、もちろんたたき台をつくるために庁内検討を行います。その庁内検討でまとめたものをもちまして、公募区民の方も入っていただく予定でおりますので、出していく形になろうかと思います。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから、この「求められる庁舎機能」ということもここで４点出ていますけれども、これでお聞きします。きょうの質疑の中で、これに対してまた追加で要望する形の進め方なのか、その辺はどう進めるのかわからなかったので、それは後で説明を求めました。","respondent":"立木経理課長、大倉委員長","answer":"こちらの庁舎機能検討委員会ですけれども、こちらも２０人程度の中に、お話しする場はきちっと考えていかなければいけないと考えています。今後、お話しさせていただければというところで、今のところはまだ検討の段階です。進め方についてですが、本日、新庁舎の機能についてということで先ほど来お話があったとおり、再編も含めた協議が今されているところであります。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この庁舎に何を求めるかは、きょうの段階ではないですね。そこだけ確認して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"あくまで交渉ですから、交渉が先に進まない限りは進みようがないのが本来の状況だと私は思います。せっかく委員長が新庁舎のあり方についてこのように議題というか話し合いに載せていただいたわけですから、議論していいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどのようなご説明もありましたけれども、改めてこの説明の中で、区庁舎跡のアリーナ構想についても説明したのでしょうか。そこははっきりと教えてほしいと求めました。","respondent":"立木経理課長","answer":"きちんと４つ、それぞれこのような理由、なぜそこではなく広町なのかというところも含めましてご説明をさせていただいたところです。取り壊しをして、その後、何かしらのにぎわい施設なりを今後検討していくというところまではお話ししていますが。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜここに名前が挙がっていないのか理由を伺いたいと思います。先ほどの質問について伺います。","respondent":"立木経理課長","answer":"そのほかにも、現在検討中というところでは７区ほど私どもがつかんでいるところではございまして、その中にもちろん世田谷区も入ってあります。進め方の部分ですとか、検討内容とか、私どもがうまくできるように進めていくという形の研究をしていきたいと考えているところです。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"４番目の委員会ですけれども、これは公開でしょうか。２０人程度と全体が既に決まっていますけれども、何人ぐらいの公募区民の方を想定しているのか、今現在のお考えがあれば伺いたいと思います。","respondent":"立木経理課長","answer":"先ほどご説明させていただいた、説明に回らせていただいている団体から代表者を出していただいたり、人数はこれからということになろうかと思います。これからどのような分野がいいのか人選を進めてまいりたいというところで、まだ具体的な人選まではいっていない状況です。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひご検討ほしいと求めましたけれども、いかがでしょうか。２０２１年度で基本構想となっていましたけれども、このような区民参加の検討、組織を立ち上げる考えはあるのでしょうか伺いたいと思います。","respondent":"立木経理課長","answer":"人数に関しましても、他のメンバーとのバランスを考えながら検討してまいります。とりあえず来年度に関しましては「庁舎機能検討委員会」という形をとらせていただいて、来年度をかけて検討してまいりたいと考えております。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"区としては延床面積、現在の４万３,１０１m2を超えておよそどれぐらいを確保したいと今考えているのかを伺いたい。そして、敷地が大幅に狭くなってそれが可能なのかを伺いたいと思います。","respondent":"立木経理課長","answer":"所管は建設委員会となりますので、私からは詳細はお答えはできないですが、きちっとＪＲとの協議を詰めているということは聞いているところです。前回の庁舎のあり方の中でご説明させていただいた想定敷地８,３００m2に関しましては、本庁舎、議会と第三庁舎だけで言いますと。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"大体どれぐらいの土地と交換するのかを経理課長は知らないという状況なのですか。伺ったのは、現在は延床面積は４万３,１０１m2で、では大体何平米ぐらいを確保することを目標にされているのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"ですから、必要な機能や基本構想の策定をしていない中で敷地面積を確定するこのＤ案は順序があべこべだし間違いだと共産党は言っているわけです。Ｄ案は白紙にして、情報公開と住民参加で進めるべきだと思いますけれども、これはいかがか尋ねました。","respondent":"立木経理課長","answer":"一番適している部分と、あとはこれまで本委員会の中でご議論を進めてきていただいた中では、このＤ案を撤回することは考えてございません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"ですから、再編自体を、協議をやめろと言っているわけではないのです。私たちはこれまで進んでこなかった大井プレイス構想が動き出したきっかけとなったのは区役所建て替え計画なのですかと質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２番のところが「求められる庁舎機能」ということで、４番目がまさに大事な区民の意見をどうやって集約をしていくのかという資料だというご提示です。こういった部分についてもほかのチームを組むのかどうか、組んでいるのかどうか、そこの確認が一つ。","respondent":"立木経理課長","answer":"こちらの「庁内検討」のほうに５つほど挙げさせていただいた後半に。事務局機能、まとめに関しましては、今のところ、経理課ですると考えているところです。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"協議体ですから、全員でチームとなってやっていくということだとは思うのですけれども、そこの責任の所在を確認させていただきました。最後に確認なのですが、意見公募、パブリックコメント等で区民の意見は聞くということか確認をします。","respondent":"立木経理課長","answer":"防災・環境の面に関しましても、きちっと議論できる形でプロジェクトチーム等も恐らく立ち上げることになるかと思います。検討委員会、それから基本構想それぞれに関しましても、そこら辺はパブリックコメント等も含めましてやらせていただきたいと思います。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょうど品川区の長期基本計画の１０年間と重なる、２０３０年の目標までに重なることと、あとは庁舎の建て替えが大きく重なるわけです。環境にも配慮していただきたい、また、防災のこともやっていただきたいという思いで申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"「求められる庁舎機能」も、区にお願いしたり、一つの階でできるだけ多くの業務をそこで完結するような仕組みをつくってほしいと求めました。長く区役所が１００年以上もつような庁舎をつくっていただきたいということで、庁舎機能検討ということですから、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"経理課長にお尋ねしたい。この資料をつくるのにどれぐらいの役所の担当の方たちが目を通されて推敲なりチェックされているのか説明を求めました。","respondent":"立木経理課長","answer":"こちらの資料に関しましては、所管は経理課になりますが、そちらでたたき台をつくりまして、その後、上層部までこの内容で議会に諮らせていただきたいというところで、そういった区の組織体の中でやらせていただいているところです。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"具体的にこの５項目を出していただいて、逆にあちらこちらから揚げ足を取られるような質問をされるおそれもあると思うのですけれども、そこのところはどのようにお考えか尋ねました。","respondent":"立木経理課長","answer":"端的に少し箇条書きに資料はつくらせていただいておりますので、そこら辺は関係各位にはきちっと説明できるものを今後も用意する形で進めていきたいと考えております。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"５つの機能がありますけれども、２と３の「など」という言葉もありますけれども、そこはどうお考えか尋ねました。","respondent":"立木経理課長","answer":"このような形で「など」という表現にまとめさせていただいたので、誤解を受けないように、資料等を用意するときにはわかりやすい形をきちっと考えていきたいと考えています。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"前回のＤ案とかＡ案とかありましたけれども、デリケートな問題なので、表現をしっかりと注意しながら取り扱ってほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"せお委員","kind":"確認","question":"１点、確認なのですけれども、庁舎機能検討委員会ですけれども、庁舎機能を区民の方々と一緒に議論する場は、この庁舎機能検討委員会だけということになりますか尋ねました。","respondent":"立木経理課長","answer":"委員おっしゃるとおり、こちらの庁舎機能検討委員会の中でご意見、議論なりをしたいと考えております。こちらだけというところで今のところは考えております。","id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"障害児の立場からはこのようなことをしてほしい、一緒の場所で相互理解を深めていいものにしていただきたいと、まず要望したいと思います。なので、そのような方々が利用する施設なども併設していただけたらと、ここでは要望で終わらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１点目に「関係団体への説明」のところで、説明もしていただきたいと思うのですけれども、そこら辺はどのように考えられているのか。それはどの辺になるのか、区としてはどう考えているかお伺いします。","respondent":"立木経理課長","answer":"その都度きちっとこれまで説明してきた団体の皆さんを通してだったりとか、もしくはまた検討委員会等、それから基本構想の検討に当たりましては。例えば個別の説明会を開くところまでは、今の段階で各地域を回って説明会というようなことは、今のところ考えておりません。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"提案","question":"提案の案の庁内決定がなされたことは示されていると思います。その根拠を伺いたいのと、そもそも提案されたＤ案は誰によって提案されて、それぞれご説明ほしいと求めました。","respondent":"立木経理課長","answer":"１つ目の「関係団体への説明」に関しましては、そういったオープンな形でご説明を進めさせていただいているところです。やはり同じような議論の中でＤ案が一番望ましいのではないかという形で本委員会に区としてＤ案で行きたいというような形のご説明をさせていただいた。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"提案","question":"オープンな形でと、それは内緒にしてくださいなどというのは当然ないわけですから、そこだけでは広がらない部分が往々にしてあるわけですから。","respondent":"榎本総務部長","answer":"その中で、ある程度、それに基づいて今度は経営会議の場でどのように検討していけばいいのかという形のものができたところです。そのようなものも総合的に考えた場合にどのような形がいいのかを積み重ねてきた中で、そこに諮ってこの方針でいこうという形になりました。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問・要望","question":"「ほぼ同じ内容の」というところに私としてはどのような内容なのかを参考までにお聞きしたいと思います。地区連合町会には全部ご説明が終わったのかの確認と、ここは１７団体となっていますけれども、状況を説明するよう求めました。","respondent":"立木経理課長","answer":"それからＡ３判の候補地案が４つ入ったもの、それから地図の入ったまちづくりの部分の３枚セットでご説明させていただいたところです。品川区障害者７団体協議会、品川区商店街連合会、品川産業協会等々に説明をさせていただいているところです。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"必要かと思っているところですが、今後の予定はどのように説明をされていくのか、そこら辺をひとつ教えてほしいと求めました。子育ての部分を取り出して、そうした利便性向上の庁舎機能も考えられるのではないかと思いますが、その点はいかがか尋ねました。","respondent":"立木経理課長","answer":"今回、庁舎の建て替え候補地を絞り込んで検討を進めていくということで、今回、初めて町の方、区民の方、関係団体の方にはご説明したことになります。","id":"exchange-033"},{"speaker":"こんの委員","kind":"提案","question":"どうしてもワンストップは、１階に何でも置きたいというか、結構スペースが必要なのです。私は、ここは少し取り出してもいいと思ったので、提案をしてみましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"おくの委員","kind":"意見","question":"今の５つの機能なのですけれども、これは何で５つの機能なのかが、これだけに限られるということではないと理解しておいていいですよねとの意見を述べました。","respondent":"立木経理課長","answer":"機能検討に関しましては、子ども系の部分は、大きな項目として考えていかなければいけない部分だと考えています。きちっと検討を進めていくという形で、何かしらチームなり作業部会なりという形をつくっていくことになろうかと考えています。","id":"exchange-035"},{"speaker":"おくの委員","kind":"質問","question":"施設の併設、障害者施設とか、特別養護老人ホーム施設とか、あるいは保育所、そのようなことも思い浮かびます。そのようなことも私などは思い浮かべたりするのですが、そのようなこともあり得ると考えておいていいのか尋ねました。","respondent":"立木経理課長","answer":"これから検討分野をスタートしますので、そういった中で、まずは庁内検討の中での議論になろうかと思っています。そういった中で、必要性はきちっと精査をさせていただいてというところになると思っているところです。","id":"exchange-036"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、事例研究として、渋谷区、豊島区だけではなく、世田谷区を並べて特記しておいていただきたいと考えています。２番目の「求められる庁舎機能」の中の（２）、具体的には結局、災害対策本部として機能することを中心に考えられておられるのか尋ねました。","respondent":"立木経理課長","answer":"庁舎の機能として絶対必要なものは、当然、災害対策本部としての機能と考えているところです。今回、例示をさせていただいているところですので、これもいろいろな事例を検討しながら研究していくです。","id":"exchange-037"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから、そのように積極的な応募があるような選び方を公募区民でもしていただきたいということも、私の要望として申し上げておきたいと思います。会議は公開にしていただきたいし、議事録もきちっと公開していただきたいという、私の要望として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/990135?Template=document&Id=6080#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":29904,"voices":79}},{"id":"r01-20191206-18","meetingId":"r01-cm12","date":"2019年12月6日","dateIso":"2019-12-06","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時０９分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"つる委員","kind":"確認","question":"視察の場で園長先生にも少し伺いましたけれども、横断幕とか、そうしたところでの掲示とか掲出ができるのかということです。ウェルカムの気持ちを表示できるようなものが、そもそもできるのかどうかという、まずその確認したいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"何回もご説明申し上げているラストマイルから競技場の入り口までは、競技会場の中は組織委員会でやっているという区分けになっております。","id":"exchange-001"},{"speaker":"つる委員","kind":"質問・要望","question":"この間もずっと確認はさせていただいた中で、今、ご答弁にもありました。確認が必要かもしれませんけれども、子どもたちの心に残るような機会をぜひつくってほしいと求めましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"今のつる委員と関連して質問いたします。何かしらで携われないかということはずっと要望していたのですが、幼保も含めて、イメージのようなものがあれば教えてほしいと求めました。","respondent":"工藤指導課長","answer":"大会の実施年におきまして、実施年の来年度というのは、もちろん協力していくというところではあります。何か取り組みとして、教育委員会として行っていくことというのは、さらに考えていきたいとは思ってあります。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"今どういう状況にあるのかというのをお知らせいただきたいのですが、最終決定がいつになるのかとか、子どもたちの観戦機会の創出というところでの流れをお聞きしたいと思います。","respondent":"工藤指導課長","answer":"本日の視察先で説明がありましたように、先ほど申し上げた４６グループのうち３０グループはホッケー会場に、仮で当たっているところです。正直申し上げて、今、教育課程の編成の時期になっておりますので、今のところは暫定ということで、その日程で考えていただいているです。","id":"exchange-004"},{"speaker":"新妻委員","kind":"確認","question":"まだ決定はされていないということで、確認をさせていただきました。会場に入れる人が、これは安全面も含めて、そういう引率者を多くさせてもらえるという考え方でいいのか尋ねました。","respondent":"工藤指導課長","answer":"それが十分来るかどうか、その数がそのまま来るかどうかというのは、まだ私どもでも把握ができないところです。交通機関で移動するところに支援する方をつけるというところでの考えはありますので、そういったところでも支援はしていきたいと考えています。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"今の質問に関連してなのですが、会場内に入れるかどうかということも加味されているかもしれませんけれども、現段階でわかることがあれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しな助の活躍の場としては、現在のところは引率というのは想定には入れておりません。なかなか難しいかなというところですので、現時点では学校なり、幼稚園や保育園で考えていただきたいと思っているところです。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"具体的な予算も含めて、来年度の話になると思うのですが、いろいろ考えて想定していることはあると思うのです。園にとっては１日とか２日の話かもしれませんが、そうしたところの支援の想定というのは、今現在で何かあるのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"園で確保できれば一番いいのですけれども、やはり大会期間中は人手不足も言われておりますし、必ず確保できるかということも難しいところがあります。そのあたりは、様子を見ながら検討して、教育委員会とも話し合いをしながら決めていきたいと考えています。","id":"exchange-007"},{"speaker":"つる委員","kind":"確認","question":"東京都のいろいろな会議録とかを確認すると、人員についてどうするかというところまでは言及がなかったのですけれども、微に入り細に入る対応をぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"押しつけにならないようにしていくべきだということと、これは率直に伺いたいのですけれども、そこを伺いたいと思います。オリンピック・パラリンピックですから、１点、質問のところだけお願いいたします。","respondent":"工藤指導課長","answer":"そういった和の心やおもてなしの心を大事にするというところだと考えていますので、各学校、また園に指導しているところがあります。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回視察させていただいて、文化に触れるという形でやられていらっしゃいますので、やはり押しつけにならないようにやってほしいと求めました。そこを伺いたいのと、そういった観点での取り組みはどういったことをやられているのか、そこも伺えればと思います。","respondent":"工藤指導課長","answer":"全校ということで区内では取り組んだところでございまして、今年度は引き続き行うという学校が、またその取り組みを継続しているところがあります。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"この１８ページ・１９ページにも載っているということで、そういったところでも関心を持っていただいて、進めていってほしいと求めました。今回の大会を契機に、品川でのインクルーシブ教育が進んだと言われるような形で、ぜひ取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"小芝委員","kind":"質問","question":"幼稚園の先生がこういったことを幼稚園児に教えているのでしょうけれども、昔は多分、区でこういう時間を確保しているものなのでしょうか。それとも、それぞれの幼稚園独自のやり方に沿っているものなのか尋ねました。","respondent":"工藤指導課長","answer":"私どもの研修の機会の中でも設定できるように検討してまいりますけれども、知見を増やしていただくことも今後は考えられると思います。そういった考えでも検討していきたいと考えています。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"区立幼稚園９園に、すごくすばらしい地域力の底上げになるかなと思うのですけれども、いかがでしょうか。３キャラクター、とてもいいかなと思うのですけれども、いかがか尋ねました。","respondent":"工藤指導課長、辻オリンピック・パラリンピック準備課長","answer":"教育委員会の支援が必要な部分というのは、各園が実施できるという方向で、お声があればそれを支援していきたいとは考えてあります。できるだけ広めていくというのは、大事なところと考えていますので… ３キャラについてのご質問です。それからスポーツ推進課が行う子ども向けのスポーツイベント等に出る予定もありますし、出演予定がなければ周りだけ、貸し出しもしておりますので。","id":"exchange-013"},{"speaker":"西村委員","kind":"質問","question":"５つの視点を全て取り入れた視点を持って、各学校ですとか幼稚園が取り組んでいらっしゃるのかどうかを、改めてお伺いさせてください。２点目が、パラリンピックの教育の推進ですとか、学校運営計画に位置づけられているのかどうかというのを尋ねました。","respondent":"工藤指導課長","answer":"それは学校独自に取り組むところなのですが、この取り組みを選んだからこれというところの考えというのは、各学校が決めて進めているところです。","id":"exchange-014"},{"speaker":"西村委員","kind":"意見","question":"一生に一度あるかどうかという、日本で行われるオリンピック・パラリンピックですので、ぜひ障害を持ったお子さんたちに、特にパラリンピックを見る機会とか体験する機会があるといいなと思いますので、引き続きお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"こういう場合は区が何か協力する形で、結構ハードルが高いことを実現されているのだなと、それがどのようにできたのかということを伺いたいです。この方たちがどういうことを尊重して、ぜひそうであってほしいという趣旨の質問なのですけれども、説明を求めました。","respondent":"工藤指導課長","answer":"学校で給食を用意するということで行っている取り組みがありますので、例えばいらっしゃるというところで行っているという事業はあります。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"なぜそういうことが必要なのかということ、もし今後もこういうことがあれば、ぜひその前後の教育のほうも丁寧にやってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"このチラシをつくられたのは、どこなのでしょうか。なぜそれを聞くかというと、切り込みが入っているかと思うのですが、これにないのは何か意図があるのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"全体が大きい中、応募がある部分だけ先に、これをつくらせていただいています。全体のチラシをつくるときには、通常どおりにＳＰコードを入れたりなどをしますので、そこのところはご容赦いただきたいと思います。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、積極的にこういうチラシがありますという広報をぜひ心がけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"ＬＩＮＥスタンプの販売についてお伺いしたいのですけれども、機運醸成には、非常に役立つものかと考えています。費用は大体お幾らぐらいかかったのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回のＬＩＮＥスタンプの販売に関しましては、もともと私どもの持っている３キャラのポーズをもとに、職員が申請をしてやっておりますので、特段、費用というのはかかっておりません。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"この絵は、新しく描いたのではないということですか。それもあまり費用がかかっていないという意味でよろしいのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"３キャラのポーズといいますか、顔だちとかは、幾つも在庫を持っておりまして、その中からＬＩＮＥのスタンプに適当なものとフレーズを組み合わせて、今回はつくっております。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"すばらしい工夫、在庫活用ということで、すばらしい取り組みだと考えています。もちろん区外の方も使ってほしいのですけれども、このＬＩＮＥスタンプの周知というのは、どのようにお考えなのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"インスタグラムですとかツイッター、それからホームページ、それからＬＩＮＥ自体に登録している方向けにお知らせするということを考えております。チラシとして、ＬＩＮＥスタンプを始めましたというのでまたつくって、入れる等の形でのお知らせをしたいと考えています。","id":"exchange-022"},{"speaker":"つる委員","kind":"提案","question":"ＬＩＮＥスタンプですが、これは昨年の８月の委員会で具体的に提案させていただきました。１２０円ないし５０コインというところで、区の予算とかそういうところでは、どういう名前での収入の位置づけになっていくのか説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"２点ご質問いただきました。微々たるものなのかなという認識でおりまして、おそらく雑入ということで入るのではないかと考えています。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"この委員会が妥当かどうか、あれですけれども、雑入で入ってくるのは何％ぐらいなのですか。どのぐらいの人が買ってくれたというのは、いろいろな形でわかる方法があるのでしょうけれども、そういうのもわかったりするのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"詳しい数字は出ていないのですけれども、量数によって、たしか利率が変わると聞いております。それは人数がわかることで、それで何％という割合になりますので、そこでわかることになります。","id":"exchange-024"},{"speaker":"西村委員","kind":"質問","question":"「Ｃｈａｌｌｅｎｇｅ ＆ Ｍｏｖｅ」で１点だけお伺いさせてください。対象年齢を小学校４年生以上に定められた理由だけ説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらは開催が夜だということで、遅くなるので小学生の高学年以上といいますか、４年生以上と今回はしています。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/985009?Template=document&Id=6566#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":20516,"voices":69}},{"id":"r01-20191211-10","meetingId":"r01-cm12","date":"2019年12月11日","dateIso":"2019-12-11","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"大倉委員","kind":"確認","question":"実施後、ＩＣＴ推進会議にて今回の方法について意見交換を行い、今後もこの方法で実施可能ではないかとの確認ができました。以上、ご検討のほど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"確認なのですけれども、この招集通知については、申し合わせ確認事項とか、何か議会の取り決めというのはそもそもあるのか尋ねました。","respondent":"米田区議会事務局長","answer":"通知するということの記載のみでして、どの媒体をもってということについては記載はありません。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"そういう意味で、今、規定があるのかないのか確認して、特に問題はないと確認できましたので、結構です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201447?Template=document&Id=5340#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":7776,"voices":34}}]);
